def _get_array(val, shape, default=None, dtype=np.float64):
    """Ensure an object is an array with the specified shape."""
    import numpy as np
    if val is None:
        return np.full(shape, default, dtype=dtype)

    arr = np.asanyarray(val, dtype=dtype)
    if arr.shape != shape:
        if arr.size == 1:
            return np.full(shape, arr.item(), dtype=dtype)
        raise ValueError(f"Expected shape {shape}, but got {arr.shape}")
    return arr

