def _uncached_match(self, text, pos, cache, error):
        """Return length of match, ``None`` if no match."""
        if pos >= len(text):
            return 0 if self.optional else None

        for i in range(pos, len(text)):
            if self.match_char(text[i]):
                return i - pos + 1
        return None

