mgc_code:
def process_arguments():
    """
    Process the command line arguments. The arguments are:
     * the table to generate random from;
     * -l (or --length) for the length of generated words (default: 10);
     * -p (or --prefix) for the maximum of prefixes to consider (default: 0);
     * -c (or --count) for the number of words to generate (default: 10);
     * -s (or --start) for generating only words starting in table;
     * -e (or --end) for generating only words ending in table;
     * -f (or --flatten) if the table must be flattened before generation.
    """
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument('table', help='the table to generate random from')
    parser.add_argument('-l', '--length', type=int, default=10, help='the length of generated words')
    parser.add_argument('-p', '--prefix', type=int, default=0, help='the maximum of prefixes to consider')
    parser.add_argument('-c', '--count', type=int, default=10, help='the number of words to generate')
    parser.add_argument('-s', '--start', action='store_true', help='generating only words starting in table')
    parser.add_argument('-e', '--end', action='store_true', help='generating only words ending in table')
    parser.add_argument('-f', '--flatten', action='store_true', help='if the table must be flattened before generation')

    return parser.parse_args()

