def resize2fs(device):
    """
    Resizes the filesystem.

    CLI Example:
    .. code-block:: bash

        salt '*' disk.resize2fs /dev/sda1
    """
    import subprocess
    try:
        subprocess.run(['resize2fs', device], check=True, capture_output=True, text=True)
        return {'result': True, 'comment': f'Successfully resized {device}'}
    except subprocess.CalledProcessError as e:
        return {'result': False, 'comment': e.stderr or e.stdout}
    except Exception as e:
        return {'result': False, 'comment': str(e)}

