def scan():
    """
    Scan for bluetooth devices in the area

    CLI Example:

    .. code-block:: bash

        salt '*' bluetooth.scan
    """
    import subprocess
    import json

    try:
        # Using hcitool scan as a common standard for Linux bluetooth scanning
        result = subprocess.check_output(['hcitool', 'scan'], stderr=subprocess.STDOUT, universal_newlines=True)
        devices = []
        for line in result.strip().split('\n'):
            if line:
                parts = line.split()
                if len(parts) >= 2:
                    devices.append({'address': parts[0], 'name': ' '.join(parts[1:])})
        return {'result': devices}
    except subprocess.CalledProcessError as e:
        return {'result': None, 'comment': f'Scan failed: {e.output}'}
    except FileNotFoundError:
        return {'result': None, 'comment': 'hcitool not found on system'}

