def get_outcome_results(self, course_id, include=None, outcome_ids=None, user_ids=None):
        """
        Get outcome results.

        Gets the outcome results for users and outcomes in the specified context.
        """
        query = self.db.table('outcome_results').where('course_id', course_id)

        if include:
            query = query.where('include', include)
        if outcome_ids:
            query = query.where('outcome_id', 'in', outcome_ids)
        if user_ids:
            query = query.where('user_id', 'in', user_ids)

        return query.get()

