def comment_magic(source, language='python', global_escape_flag=True):
    """Escape Jupyter magics with '# '"""
    if not source:
        return source

    lines = source.splitlines(keepends=True)
    result = []
    escaped = False

    for line in lines:
        stripped = line.strip()
        if not stripped:
            result.append(line)
            continue

        is_magic = stripped.startswith('%')

        if is_magic:
            if not escaped:
                result.append(f"# {line}")
                escaped = True
            else:
                result.append(f"# {line}")
        else:
            result.append(line)
            if not global_escape_flag:
                escaped = False

    return "".join(result)

