mgc_code:
def exec_func_src(func, globals_=None, locals_=None, key_list=None,
                  sentinal=None, update=None, keys=None, verbose=False,
                  start=None, stop=None):
    """
    execs a func and returns requested local vars.

    Does not modify globals unless update=True (or in IPython)

    SeeAlso:
        ut.execstr_funckw
    """
    if globals_ is None:
        globals_ = {}
    if locals_ is None:
        locals_ = {}
    if key_list is None:
        key_list = []
    if update is None:
        update = False

    # Create a copy of globals to avoid modification unless update=True
    exec_globals = globals_ if update else globals_.copy()

    # Execute the function source
    exec(func, exec_globals, locals_)

    # If update is True, sync the modified globals back
    if update:
        globals_.update(exec_globals)

    # Return requested local variables
    result = {}
    for key in key_list:
        if key in locals_:
            result[key] = locals_[key]
        elif key in exec_globals:
            result[key] = exec_globals[key]

    return result

