def refine_water_bridges(self, wbridges, hbonds_ldon, hbonds_pdon):
        """A donor atom already forming a hydrogen bond is not allowed to form a water bridge. Each water molecule
        can only be donor for two water bridges, selecting the constellation with the omega angle closest to 110 deg."""
        refined_bridges = []
        donor_used = set()
        for hb in hbonds_ldon:
            donor_used.add(hb[0])
        for hb in hbonds_pdon:
            donor_used.add(hb[0])

        water_donors_count = {}
        potential_bridges = []

        for bridge in wbridges:
            donor = bridge[0]
            if donor in donor_used:
                continue

            omega = bridge[-1]
            diff = abs(omega - 110.0)
            potential_bridges.append((diff, bridge))

        potential_bridges.sort(key=lambda x: x[0])

        for diff, bridge in potential_bridges:
            donor = bridge[0]
            count = water_donors_count.get(donor, 0)
            if count < 2:
                refined_bridges.append(bridge)
                water_donors_count[donor] = count + 1

        return refined_bridges

