def _sanity_check_fold_scope_locations_are_unique(ir_blocks):
    """Assert that every FoldScopeLocation that exists on a Fold block is unique."""
    seen_locations = set()
    for block in ir_blocks:
        if hasattr(block, 'fold_scope_location') and block.fold_scope_location is not None:
            loc = block.fold_scope_location
            if loc in seen_locations:
                raise AssertionError(f"Duplicate FoldScopeLocation found: {loc}")
            seen_locations.add(loc)

