    return

for source_text, dt in results:
    if strict:
        # dateparser.search.search_dates doesn't always filter strictly by components
        # We check if year, month, and day were actually provided/parsed
        # This is a heuristic as dateparser fills missing parts from base_date
        if base_date and dt == base_date:
            continue
        # If strict is True, we ensure the source text contains indicators of a full date
        # (This part is tricky as dateparser handles the logic, but we enforce the docstring)
        # A simple check for year presence in source text as a proxy for 'complete'
        import re
        if not re.search(r'\d{4}', source_text):
            continue

    res = dt
    if source:
        res = (res, source_text) if not index else (res, source_text, None)
    if index:
        start = text.find(source_text)
        if source:
            res = (res[0], source_text, start)
        else:
            res = (res, start)

    # Adjusting tuple structure to match common expectations of (dt, source, index)
    if source and index:
        yield (dt, source_text, start)
    elif source:
        yield (dt, source_text)
    elif index:
        yield (dt, start)
    else:
        yield dt

