def post_prob_scheme(t_table, stanza, scheme):
    """
    Compute posterior probability of a scheme for a stanza, with probability of every word in rhymelist
    rhyming with all the ones before it
    """
    prob = 1.0
    rhyme_groups = {}
    for i, char in enumerate(stanza):
        if char == '-':
            continue
        if char not in rhyme_groups:
            rhyme_groups[char] = []

        group = rhyme_groups[char]
        if group:
            word_i = t_table[i]
            word_prev = t_table[group[-1]]
            prob *= t_table.get_rhyme_prob(word_i, word_prev)

        group.append(i)
    return prob

