mean, variance = tf.nn.moments(x, axes=axis, keepdims=True)
x_normalized = (x - mean) / tf.sqrt(variance + epsilon)

if use_affine:
    shape = x.shape
    if data_format == 'channels_last':
        channel_dim = shape[-3]
        gamma_shape = [1, channel_dim, 1, 1] if data_format == 'channels_first' else [1, channel_dim, 1, 1]
        # Correcting shape for broadcast based on data_format
        if data_format == 'channels_last':
            gamma_shape = [1, shape[1], 1, 1]
        else:
            gamma_shape = [1, 1, shape[1], 1]
    else:
        gamma_shape = [1, shape[1], 1, 1]

    if gamma_init is None:
        gamma = tf.Variable(tf.ones(gamma_shape), name='gamma')
        beta = tf.Variable(tf.zeros(gamma_shape), name='beta')
    else:
        gamma = tf.Variable(gamma_init, name='gamma')
        beta = tf.Variable(tf.zeros(gamma_shape), name='beta')

    return gamma * x_normalized + beta

return x_normalized

