def _get_setting(self, setting_dotted_name, default=None):
        """Return the value of a potentially nested dict setting.

        E.g., 'DATABASES.default.NAME

        """
        parts = setting_dotted_name.split('.')
        val = self.settings
        try:
            for part in parts:
                val = val[part]
            return val
        except (KeyError, TypeError):
            return default

