def find(self, obj, forced_type=None,
             cls=anyconfig.models.processor.Processor):
        """
        :param obj:
            a file path, file, file-like object, pathlib.Path object or an
            'anyconfig.globals.IOInfo' (namedtuple) object
        :param forced_type: Forced processor type to find
        :param cls: A class object to compare with 'ptype'

        :return: an instance of processor class to process 'obj'
        :raises: ValueError, UnknownProcessorTypeError, UnknownFileTypeError
        """
        if forced_type:
            processor_type = forced_type
        elif hasattr(obj, 'ptype'):
            processor_type = obj.ptype
        else:
            from anyconfig.models.processor import Processor
            processor_type = Processor.find_type(obj)

        if cls is not anyconfig.models.processor.Processor:
            if not issubclass(processor_type, cls):
                raise ValueError(f"Processor type {processor_type} is not a subclass of {cls}")

        return processor_type(obj)

