def create(self):
        """Create an instance of the current target in the database

        If a target with the current name and params already exists, no second instance is created.
        """
        existing = self.model.objects.filter(name=self.name, params=self.params).first()
        if not existing:
            return self.model.objects.create(name=self.name, params=self.params)
        return existing

