mgc_code:
def oauth_login(self, provider, id_column, id, attrs, defaults, redirect_url=None):
        """Execute a login via oauth. If no user exists, oauth_signup() will be called
        """
        user = self.db.get_user_by_oauth(provider, id_column, id)
        if not user:
            user = self.oauth_signup(provider, id_column, id, attrs, defaults)

        user_data = {**attrs, **defaults}
        self.db.update_user_oauth_data(user.id, user_data)

        self.session.login(user)

        if redirect_url:
            return redirect_url
        return None

