def registerInspector(self, fullName, fullClassName, pythonPath=''):
        """ Registers an Inspector class.
        """
        if pythonPath:
            import importlib.util
            import sys
            import os
            if pythonPath not in sys.path:
                sys.path.append(pythonPath)

        import importlib
        module_name, class_name = fullClassName.rsplit('.', 1)
        module = importlib.import_module(module_name)
        inspector_class = getattr(module, class_name)

        if not hasattr(self, '_inspectors'):
            self._inspectors = {}
        self._inspectors[fullName] = inspector_class()

