mgc_code:
def print_tb(tb, file=None, **kwargs):
    """
    :param types.TracebackType|types.FrameType|StackSummary tb:
    :param io.TextIOBase|io.StringIO|None file: stderr by default
    :return: nothing, prints to ``file``
    """
    import traceback
    if tb is None:
        return
    if isinstance(tb, traceback.TracebackException):
        traceback.print_exception(tb, file=file, **kwargs)
    elif hasattr(tb, '__traceback__'):
        traceback.print_exception(type(tb), tb, tb.__traceback__, file=file, **kwargs)
    elif isinstance(tb, traceback.StackSummary):
        traceback.print_stack(tb, file=file, **kwargs)
    else:
        traceback.print_tb(tb, file=file, **kwargs)

