def toVector(value):
        """
        Convert a value to a MLlib Vector, if possible.
        """
        if isinstance(value, Vector):
            return value
        elif TypeConverters._can_convert_to_list(value):
            value = TypeConverters.toList(value)
            if all(map(lambda v: TypeConverters._is_numeric(v), value)):
                return DenseVector(value)
        raise TypeError("Could not convert %s to vector" % value)

mgc_code:
def toVector(value):
        """
        Convert a value to a MLlib Vector, if possible.
        """
        from pyspark.ml.linalg import Vectors, Vector
        if isinstance(value, Vector):
            return value
        try:
            if isinstance(value, (list, tuple)):
                return Vectors.dense(value)
            return Vectors.dense([float(value)])
        except (TypeError, ValueError):
            raise TypeError(f"Value {value} cannot be converted to a MLlib Vector")

