mgc_code:
def make_tmp_name(name):
    """Generates a tmp name for a file or dir.

    This is a tempname that sits in the same dir as `name`. If it exists on
    disk at context exit time, it is deleted.
    """
    import os
    from contextlib import contextmanager

    @contextmanager
    def tmp_name_context():
        tmp = name + ".tmp"
        try:
            yield tmp
        finally:
            if os.path.exists(tmp):
                if os.path.isdir(tmp):
                    import shutil
                    shutil.rmtree(tmp)
                else:
                    os.remove(tmp)

    return tmp_name_context()

solution:
def dfs(res, path, num, target, pos, prev, multed):
    if pos == len(num):
        if target == prev:
            res.append(path)
        return
    for i in range(pos, len(num)):
        if i != pos and num[pos] == '0':  # all digits have to be used
            break
        cur = int(num[pos:i+1])
        if pos == 0:
            dfs(res, path + str(cur), num, target, i+1, cur, cur)
        else:
            dfs(res, path + "+" + str(cur), num, target,
                i+1, prev + cur, cur)
            dfs(res, path + "-" + str(cur), num, target,
                i+1, prev - cur, -cur)
            dfs(res, path + "*" + str(cur), num, target,
                i+1, prev - multed + multed * cur, multed * cur)

res = []
if not num:
    return res
dfs(res, "", num, target, 0, 0, 0)
return res

raw_output:
res = []
def backtrack(idx, prev_op, current_val, path):
    if idx == len(num):
        if current_val == target:
            res.append(path)
        return

    for i in range(idx, len(num)):
        # Handle leading zeros
        if i > idx and num[idx] == '0':
            break

        part = num[idx:i+1]
        val = int(part)

        if idx == 0:
            backtrack(i + 1, val, val, part)
        else:
            # Addition
            backtrack(i + 1, prev_op + val, current_val + val, path + '+' + part)
            # Subtraction
            backtrack(i + 1, -val, current_val - val, path + '-' + part)
            # Multiplication
            backtrack(i + 1, prev_op * val, (current_val - prev_op) + (prev_op * val), path + '*' + part)

backtrack(0, 0, 0, "")
return res

