def get_urlinfo(info):
        """
        Pick out the fragment or query part from a URL.

        :param info: A URL possibly containing a query or a fragment part
        :return: the query/fragment part
        """
        for char in ('#', '?'):
            if char in info:
                return info.split(char, 1)[1]
        return ""

