mgc_code:
def sort_canonical(keyword, stmts):
    """Sort all `stmts` in the canonical order defined by `keyword`.
    Return the sorted list.  The `stmt` list is not modified.
    If `keyword` does not have a canonical order, the list is returned
    as is.
    """
    canonical_orders = {
        'if': ['if', 'elif', 'else'],
        'try': ['try', 'except', 'else', 'finally'],
        'for': ['for', 'else'],
        'while': ['while', 'else'],
    }
    order = canonical_orders.get(keyword)
    if not order:
        return list(stmts)

    def sort_key(stmt):
        try:
            return order.index(stmt)
        except (ValueError, AttributeError):
            return len(order)

    return sorted(stmts, key=sort_key)

