mgc_code:
def read_prologs(filename):
    """
    Given a filename, search for SST prologues
    and returns a dict where the keys are the name of the
    prolog (from the "Name" field) and the keys are another
    dict with keys correspding fo the SST labels in lowercase.

    prologs = read_prologs( filename )

    Common SST labels are: name, purpose, lanugage, invocation,
    arguments, description, authors, notes etc.
    """
    prologs = {}
    current_prolog = None
    current_data = {}

    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            if line.startswith('Name'):
                if current_prolog:
                    prologs[current_prolog] = current_data

                parts = line.split(':', 1)
                current_prolog = parts[1].strip() if len(parts) > 1 else "Unknown"
                current_data = {'name': current_prolog}
            elif current_prolog and ':' in line:
                parts = line.split(':', 1)
                key = parts[0].strip().lower()
                value = parts[1].strip()
                current_data[key] = value

        if current_prolog:
            prologs[current_prolog] = current_data

    return prologs

