mgc_code:
def cmd_arp_sniff(iface):
    """Listen for ARP packets and show information for each device.

    Columns: Seconds from last packet | IP | MAC | Vendor

    Example:

    \b
    1   192.168.0.1     a4:08:f5:19:17:a4   Sagemcom Broadband SAS
    7   192.168.0.2     64:bc:0c:33:e5:57   LG Electronics (Mobile Communications)
    2   192.168.0.5     00:c2:c6:30:2c:58   Intel Corporate
    6   192.168.0.7     54:f2:01:db:35:58   Samsung Electronics Co.,Ltd
    """
    from scapy.all import sniff, ARP
    import time

    devices = {}

    def process_packet(pkt):
        if pkt.haslayer(ARP):
            ip = pkt[ARP].psrc
            mac = pkt[ARP].hwsrc
            devices[ip] = {'mac': mac, 'time': time.time()}

    def get_vendor(mac):
        try:
            from scapy.all import get_mac_vendor
            return get_mac_vendor(mac) or "Unknown"
        except:
            return "Unknown"

    try:
        while True:
            sniff(iface=iface, prn=process_packet, store=0, timeout=1)
            print("\b" * 100, end="")
            print("\033[H\033[J", end="")
            now = time.time()
            for ip, info in devices.items():
                elapsed = int(now - info['time'])
                vendor = get_vendor(info['mac'])
                print(f"{elapsed}\t{ip}\t{info['mac']}\t{vendor}")
    except KeyboardInterrupt:
        pass

