def munge_source(v):
    """Take Python source code, return a pair of its parameters and the rest of it dedented"""
    lines = v.split('\n')
    if not lines:
        return tuple(), ''
    firstline = lines[0].lstrip()
    while firstline == '' or firstline[0] == '@':
        del lines[0]
        firstline = lines[0].lstrip()
    if not lines:
        return tuple(), ''
    params = tuple(
        parm.strip() for parm in
        sig_ex.match(lines[0]).group(1).split(',')
    )
    del lines[0]
    if not lines:
        return params, ''
    # hack to allow 'empty' functions
    if lines and lines[-1].strip() == 'pass':
        del lines[-1]
    return params, dedent('\n'.join(lines))

mgc_code:
def munge_source(v):
    """Take Python source code, return a pair of its parameters and the rest of it dedented"""
    import textwrap

    lines = v.splitlines()
    if not lines:
        return [], ""

    first_line = lines[0]
    if '(' in first_line and ')' in first_line:
        start = first_line.find('(') + 1
        end = first_line.rfind(')')
        params_str = first_line[start:end]
        params = [p.strip() for p in params_str.split(',') if p.strip()]
        rest = "\n".join(lines[1:])
        return params, textwrap.dedent(rest)

    return [], textwrap.dedent("\n".join(lines[1:]))

