mgc_code:
def start_stack(self, stack):
        """启动服务组

        启动服务组中的所有停止状态的服务。

        Args:
            - stack:  服务所属的服务组名称

        Returns:
            返回一个tuple对象，其格式为(<result>, <ResponseInfo>)
            - result          成功返回空dict{}，失败返回{"error": "<errMsg string>"}
            - ResponseInfo    请求的Response信息
        """
        try:
            services = self.get_services_by_stack(stack)
            if not services:
                return {}, "No services found in stack"

            for service in services:
                if service.get('status') == 'stopped':
                    self.start_service(service['id'])

            return {}, "Stack started successfully"
        except Exception as e:
            return {"error": str(e)}, None

