import subprocess
import sys
from concurrent.futures import ProcessPoolExecutor

def run_code(code):
    try:
        # Execute code and capture stderr for errors
        process = subprocess.Popen(
            [sys.executable, '-c', code],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate(timeout=10)
        if process.returncode != 0:
            return stderr or stdout
    except Exception as e:
        return str(e)
    return None

# This is a conceptual implementation as the full context of 
# 'source' (RST structure) and 'docutils' registration is external.
# We assume source is a list of blocks or a string to be parsed.

blocks = [] # Logic to extract code blocks from source would go here
# Example: blocks = [(start_line, code_content), ...]

with ProcessPoolExecutor() as executor:
    futures = {executor.submit(run_code, code): line for line, code in blocks}
    for future in futures:
        result = future.result()
        if result:
            line = futures[future]
            yield (line, result.strip())

