def spec_from_json_dict(
        json_dict  # type: Dict[str, Any]
):
    # type: (...) -> FieldSpec
    """ Turns a dictionary into the appropriate object.

        :param dict json_dict: A dictionary with properties.
        :returns: An initialised instance of the appropriate FieldSpec
            subclass.
    """
    if 'ignored' in json_dict:
        return Ignore(json_dict['identifier'])
    type_str = json_dict['format']['type']
    spec_type = cast(FieldSpec, FIELD_TYPE_MAP[type_str])
    return spec_type.from_json_dict(json_dict)

mgc_code:
def spec_from_json_dict(
        json_dict  # type: Dict[str, Any]
):
    # type: (...) -> FieldSpec
    """ Turns a dictionary into the appropriate object.

        :param dict json_dict: A dictionary with properties.
        :returns: An initialised instance of the appropriate FieldSpec
            subclass.
    """
    spec_type = json_dict.get('type')
    if spec_type == 'text':
        return TextFieldSpec(**{k: v for k, v in json_dict.items() if k != 'type'})
    elif spec_type == 'number':
        return NumberFieldSpec(**{k: v for k, v in json_dict.items() if k != 'type'})
    elif spec_type == 'boolean':
        return BooleanFieldSpec(**{k: v for k, v in json_dict.items() if k != 'type'})
    else:
        raise ValueError(f"Unknown field type: {spec_type}")

