hwc_code:
def hash_host(hostname, salt=None):
        """
        Return a "hashed" form of the hostname, as used by openssh when storing
        hashed hostnames in the known_hosts file.

        @param hostname: the hostname to hash
        @type hostname: str
        @param salt: optional salt to use when hashing (must be 20 bytes long)
        @type salt: str
        @return: the hashed hostname
        @rtype: str
        """
        if salt is None:
            salt = rng.read(SHA.digest_size)
        else:
            if salt.startswith('|1|'):
                salt = salt.split('|')[2]
            salt = base64.decodestring(salt)
        assert len(salt) == SHA.digest_size
        hmac = HMAC.HMAC(salt, hostname, SHA).digest()
        hostkey = '|1|%s|%s' % (base64.encodestring(salt), base64.encodestring(hmac))
        return hostkey.replace('\n', '')

mgc_code:
def hash_host(hostname, salt=None):
        """
        Return a "hashed" form of the hostname, as used by openssh when storing
        hashed hostnames in the known_hosts file.

        @param hostname: the hostname to hash
        @type hostname: str
        @param salt: optional salt to use when hashing (must be 20 bytes long)
        @type salt: str
        @return: the hashed hostname
        @rtype: str
        """
        import hashlib
        import os

        if salt is None:
            salt = os.urandom(20)
        elif isinstance(salt, str):
            salt = salt.encode('utf-8')

        if len(salt) != 20:
            raise ValueError("Salt must be 20 bytes long")

        hostname_bytes = hostname.encode('utf-8')
        digest = hashlib.sha256(salt + hostname_bytes).digest()

        # OpenSSH uses the first 4 bytes of the SHA256 hash as a prefix
        # and the salt encoded in base64.
        import base64
        salt_b64 = base64.b64encode(salt).decode('utf-8')

        # The actual format in known_hosts is |1|salt|hash
        # But the function asks for the "hashed form", typically the
        # representation used in the file.
        return f"|1|{salt_b64}|{base64.b64encode(digest).decode('utf-8')}"

