def _handle_consent_response(self, context):
        """
        Endpoint for handling consent service response
        :type context: satosa.context.Context
        :rtype: satosa.response.Response

        :param context: response context
        :return: response
        """
        consent_response = context.get_request_data()
        if not consent_response:
            return self.error_response("No consent response provided", 400)

        if consent_response.get("status") == "approved":
            context.set_consent_granted(True)
            return self.success_response()
        elif consent_response.get("status") == "denied":
            context.set_consent_granted(False)
            return self.error_response("Consent denied by user", 403)
        else:
            return self.error_response("Invalid consent status", 400)

