def destroy_ebs_volume(connection, region, volume_id, log=False):
    """ destroys an ebs volume """
    if log:
        print(f"Destroying EBS volume {volume_id} in region {region}...")

    ec2 = connection.get_client('ec2', region_name=region)
    response = ec2.delete_volume(VolumeId=volume_id)

    if log:
        print(f"Successfully destroyed EBS volume {volume_id}")

    return response

