mgc_code:
def dict2DingoObjDict(data):
    """
    Turn a dictionary of the form used by DINGO
    (i.e., a key is mapped to either another dictionary,
    a list or a value) into a DingoObjDict.
    """
    class DingoObjDict(dict):
        def __getattr__(self, name):
            if name in self:
                return self[name]
            raise AttributeError(f"'{type(self).__name__}' object has no attribute '{name}'")

    def convert(item):
        if isinstance(item, dict):
            return DingoObjDict({k: convert(v) for k, v in item.items()})
        elif isinstance(item, list):
            return [convert(i) for i in item]
        return item

    return convert(data)

