mgc_code:
def table_has_constraint(table, name, db):
    """Utility to find a constraint name in alembic migrations"""
    inspector = db.engine.connect().connection.engine.connect() if hasattr(db, 'engine') else None
    if not inspector:
        return False

    from sqlalchemy import inspect
    inspector = inspect(db.engine)

    for constraint in inspector.get_unique_constraints(table):
        if constraint['name'] == name:
            return True

    for constraint in inspector.get_primary_key(table):
        if constraint.get('constrained_columns') and name in str(constraint):
            return True

    for constraint in inspector.get_foreign_keys(table):
        if constraint['name'] == name:
            return True

    return False

