mgc_code:
def fmt_routes(bottle_app):
    """Return a pretty formatted string of the list of routes."""
    routes = []
    for route in bottle_app.routes:
        method = route.method
        path = route.rule
        callback = route.callback.__name__ if hasattr(route.callback, '__name__') else str(route.callback)
        routes.append(f"{method:<7} {path:<20} {callback}")

    if not routes:
        return "No routes defined."

    header = f"{'Method':<7} {'Path':<20} {'Callback'}"
    separator = "-" * len(header)
    return "\n".join([header, separator] + routes)

