mgc_code:
def grouper(n, iterable):
    """
    >>> list(grouper(3, 'ABCDEFG'))
    [['A', 'B', 'C'], ['D', 'E', 'F'], ['G']]
    """
    chunk = []
    try:
        for _ in range(n):
            chunk.append(next(it))
        yield chunk
    except StopIteration:
        if chunk:
            yield chunk
        break

