if is_cython(func):
    attrs = [
        "__code__", "__annotations__", "__defaults__", "__kwdefaults__"
    ]

    if all(hasattr(func, attr) for attr in attrs):
        original_func = func

        def func():
            return

        for attr in attrs:
            setattr(func, attr, getattr(original_func, attr))
