mgc_code:
def get_ngrams(path):
    """Returns a list of n-grams read from the file at `path`."""
    with open(path, 'r', encoding='utf-8') as f:
        text = f.read().split()
    ngrams = []
    for n in range(1, len(text) + 1):
        for i in range(len(text) - n + 1):
            ngrams.append(tuple(text[i:i+n]))
    return ngrams

