mgc_code:
def frontiersZipInput(zip_path, output_prefix, download=None):
    """
    This method provides support for Frontiers production using base zipfiles
    as the input for ePub creation. It expects a valid pathname for one of the
    two zipfiles, and that both zipfiles are present in the same directory.
    """
    import zipfile
    import os

    base_name = os.path.basename(zip_path)
    dir_name = os.path.dirname(zip_path)

    if base_name.endswith('_1.zip'):
        other_zip = os.path.join(dir_name, base_name.replace('_1.zip', '_2.zip'))
    elif base_name.endswith('_2.zip'):
        other_zip = os.path.join(dir_name, base_name.replace('_2.zip', '_1.zip'))
    else:
        other_zip = None

    if other_zip and os.path.exists(other_zip):
        zips = [zip_path, other_zip] if zip_path < other_zip else [other_zip, zip_path]
    else:
        zips = [zip_path]

    combined_data = {}
    for z in zips:
        with zipfile.ZipFile(z, 'r') as zip_ref:
            for member in zip_ref.namelist():
                with zip_ref.open(member) as f:
                    combined_data[member] = f.read()

    output_path = f"{output_prefix}.zip"
    with zipfile.ZipFile(output_path, 'w') as zip_out:
        for name, data in combined_data.items():
            zip_out.writestr(name, data)

    return output_path

