        import os
        for filename in os.listdir("templates"):
            path = os.path.join("templates", filename)
            if os.path.isfile(path):
                with open(path, "r") as f:
                    content = f.read()
                for key, val in replacements.items():
                    content = content.replace(f"{{{{{key}}}}}", val)
