mgc_code:
def are_in_interval(s, l, r, border = 'included'):
        """
        Checks whether all number in the sequence s lie inside the interval formed by
        l and r.
        """
        low, high = min(l, r), max(l, r)
        for x in s:
            if border == 'included':
                if not (low <= x <= high):
                    return False
            elif border == 'excluded':
                if not (low < x < high):
                    return False
            else:
                raise ValueError("border must be 'included' or 'excluded'")
        return True

