import csv
import os

if not files:
    return

headers = []
data_rows = []

for file in files:
    with open(file, 'r') as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
            # Assume first column is gene ID, others are counts
            gene_id = header[0]
            sample_name = os.path.basename(file).replace(ext, '')

            # Store header as [GeneID, Sample1, Sample2...]
            # We only need the first file's GeneID column
            if not headers:
                headers = [gene_id]

            headers.append(sample_name)

            # Read the rest of the file
            for row in reader:
                if not row: continue
                # Store as {gene_id: value}
                data_rows.append((row[0], row[1]))
        except StopIteration:
            continue

# Pivot data: {gene_id: [val1, val2...]}
combined = {}
for gene, val in data_rows:
    if gene not in combined:
        combined[gene] = []
    combined[gene].append(val)

# Since we might have files with different genes, we need a master list
all_genes = []
seen = set()
for file in files:
    with open(file, 'r') as f:
        reader = csv.reader(f)
        next(reader, None)
        for row in reader:
            if row and row[0] not in seen:
                all_genes.append(row[0])
                seen.add(row[0])

# Re-read files to ensure correct alignment per gene
final_data = {gene: [] for gene in all_genes}
for file in files:
    with open(file, 'r') as f:
        reader = csv.reader(f)
        next(reader, None)
        file_genes = {row[0]: row[1] for row in reader if row}
        for gene in all_genes:
            final_data[gene].append

