mgc_code:
def deploy_image(self, image_name, oc_new_app_args=None, project=None, name=None):
        """
        Deploy image in OpenShift cluster using 'oc new-app'
        :param image_name: image name with tag
        :param oc_new_app_args: additional parameters for the `oc new-app`, env variables etc.
        :param project: project where app should be created, default: current project
        :param name:str, name of application, if None random name is generated
        :return: str, name of the app
        """
        import subprocess

        cmd = ["oc", "new-app", image_name]
        if project:
            cmd.extend(["-n", project])
        if name:
            cmd.extend(["--name", name])
        if oc_new_app_args:
            cmd.extend(oc_new_app_args.split())

        result = subprocess.run(cmd, capture_output=True, text=True, check=True)

        if name:
            return name

        # Extract app name from output (usually "success" or "app created" lines)
        for line in result.stdout.splitlines():
            if "success" in line.lower() or "created" in line.lower():
                # Attempt to find the app name in the output if not provided
                parts = line.split()
                for part in parts:
                    if "/" in part or "app" in part:
                        return part

        return "deployed-app"

