mgc_code:
async def verify_chain_of_trust(chain):
    """Build and verify the chain of trust.

    Args:
        chain (ChainOfTrust): the chain we're operating on

    Raises:
        CoTError: on failure

    """
    try:
        for i in range(len(chain.certificates) - 1):
            issuer = chain.certificates[i + 1]
            subject = chain.certificates[i]
            if not subject.verify_signature(issuer.public_key):
                raise CoTError(f"Invalid signature at index {i}")

        root = chain.certificates[-1]
        if not root.is_self_signed():
            raise CoTError("Root certificate must be self-signed")

        if not root.is_trusted():
            raise CoTError("Root certificate is not in the trusted store")

    except Exception as e:
        if isinstance(e, CoTError):
            raise e
        raise CoTError(f"Chain verification failed: {str(e)}")

