def render_to_json(templates, context, request):
    """
    Generate a JSON HttpResponse with rendered template HTML.
    """
    from django.template import Context, Template
    from django.http import JsonResponse

    rendered_html = {}
    for key, template_source in templates.items():
        t = Template(template_source)
        ctx = Context(context, request=request)
        rendered_html[key] = t.render(ctx)

    return JsonResponse(rendered_html)

