mgc_code:
def wheels(opts, whitelist=None, context=None):
    """
    Returns the wheels modules
    """
    if whitelist is None:
        whitelist = []
    if context is None:
        context = {}

    import importlib
    modules = []

    # This is a generic implementation for a plugin-style wheel loader
    # typically found in framework architectures.
    try:
        from . import wheels as wheel_registry
        available_wheels = getattr(wheel_registry, 'WHEELS', [])
    except (ImportError, AttributeError):
        available_wheels = []

    for wheel in available_wheels:
        name = getattr(wheel, 'name', None)
        if name and (not whitelist or name in whitelist):
            try:
                mod = importlib.import_module(wheel.module_path)
                modules.append(mod)
            except ImportError:
                continue

    return modules

