def wait(self, timeout=None):
        """
        Blocking wait for task status.
        """
        import time

        start_time = time.time()
        while not self.done():
            if timeout is not None:
                elapsed = time.time() - start_time
                if elapsed >= timeout:
                    break
                time.sleep(0.1)
            else:
                time.sleep(0.1)
        return self.result() if self.done() else None

