mgc_code:
def close(self, reply_code=200, reply_text=''):
        """Close Channel.

        :param int reply_code: Close reply code (e.g. 200)
        :param str reply_text: Close reply text

        :raises AMQPInvalidArgument: Invalid Parameters
        :raises AMQPChannelError: Raises if the channel encountered an error.
        :raises AMQPConnectionError: Raises if the connection
                                     encountered an error.

        :return:
        """
        if not isinstance(reply_code, int):
            raise AMQPInvalidArgument("reply_code must be an integer")
        if not isinstance(reply_text, str):
            raise AMQPInvalidArgument("reply_text must be a string")

        try:
            self._channel_out.send_frame(AMQP.Frame(AMQP.Method(
                AMQP.Channel.Close(reply_code, reply_text)
            )))
        except Exception as e:
            if isinstance(e, (AMQPChannelError, AMQPConnectionError)):
                raise
            raise AMQPChannelError(f"Failed to close channel: {e}")

        self._closed = True

