    if dst not in self.listeners:
        pass  # dbg(u"%r ⇝ ↴" % (_dumpmsg(msg),))
    else:
        # dbg(u"%r → %s" % (_dumpmsg(msg), dst))
        sock = self.listeners[dst]
        deliverable.append((msg, src, sock))

del self.queue[:]

for msg, src, sock in deliverable:
    sock.gotMultipart(msg)

