import pkgutil
import inspect
from . import Feature

features = []

def _walk(mod):
    for name, obj in inspect.getmembers(mod):
        if inspect.isclass(obj) and issubclass(obj, Feature) and obj is not Feature:
            features.append(obj)

    if hasattr(mod, '__path__'):
        for loader, module_name, is_pkg in pkgutil.walk_packages(mod.__path__, mod.__name__ + '.'):
            try:
                sub_mod = __import__(module_name, fromlist=[''])
                _walk(sub_mod)
            except ImportError:
                continue

_walk(module)
return features

