def _parse_geo_file(self, file_path, run_input_dir):
        """Scan SH12A GEO file for references to external files (like voxelised geometry) and return them"""
        references = []
        try:
            with open(file_path, 'r') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    # Assuming references are paths or specific keywords in the GEO file
                    # This logic typically looks for file paths or specific markers
                    parts = line.split()
                    for part in parts:
                        if '.' in part and '/' in part or part.endswith(('.dat', '.bin', '.vox')):
                            import os
                            full_path = os.path.join(run_input_dir, part)
                            references.append(full_path)
        except IOError:
            pass
        return references

