mgc_code:
def fetchUserInfo(self, *user_ids):
        """
        Get users' info from IDs, unordered

        .. warning::
            Sends two requests, to fetch all available info!

        :param user_ids: One or more user ID(s) to query
        :return: :class:`models.User` objects, labeled by their ID
        :rtype: dict
        :raises: FBchatException if request failed
        """
        users = {}
        if not user_ids:
            return users

        # First request: basic info
        basic_info = self._request('user.get_info', {
            'user_ids': list(user_ids),
            'fields': ['name', 'profile_pic_url']
        })

        # Second request: extended info (e.g., friends, etc.)
        extended_info = self._request('user.get_info', {
            'user_ids': list(user_ids),
            'fields': ['friends']
        })

        for uid in user_ids:
            uid_str = str(uid)
            user_data = {**basic_info.get(uid_str, {}), **extended_info.get(uid_str, {})}
            if user_data:
                users[uid] = self.models.User(uid, **user_data)

        return users

def pairwise(values):
    """
    WITH values = [a, b, c, d, ...]
    RETURN [(a, b), (b, c), (c, d), ...]
    """
    return list(zip(values, values[1:]))

