mgc_code:
def check_args(arguments, data_frame):
    """
    check arguments against a command_line_dataframe.
    checks that:
    all arguments are valid
    all required arguments are present
    default values are used where needed
    """
    valid_args = data_frame['argument'].tolist()
    required_args = data_frame[data_frame['required'] == True]['argument'].tolist()
    defaults = data_frame.set_index('argument')['default'].to_dict()

    processed_args = {}

    for arg_name, value in arguments.items():
        if arg_name not in valid_args:
            raise ValueError(f"Invalid argument: {arg_name}")
        processed_args[arg_name] = value

    for req in required_args:
        if req not in processed_args:
            raise ValueError(f"Missing required argument: {req}")

    for arg in valid_args:
        if arg not in processed_args:
            processed_args[arg] = defaults.get(arg)

    return processed_args

