from concurrent.futures import ThreadPoolExecutor

def wrapper(worker):
    if isinstance(worker, tuple):
        func = worker[0]
        args = worker[1] if len(worker) > 1 else []
        kwargs = worker[2] if len(worker) > 2 else {}
        return func(*args, **kwargs)
    return worker()

with ThreadPoolExecutor() as executor:
    results = list(executor.map(wrapper, worker_defs))

return tuple(results)

