        :param event_type: number for type of event
        :returns: constructed event corresponding to ``event_type``
        :rtype: :py:class:`.Event`
        """
        for cls in Event.__subclasses__():
            if getattr(cls, 'EVENT_TYPE', None) == event_type:
                return cls()
        raise ValueError(f"No Event class found for event_type: {event_type}")

