mgc_code:
def lookup_folder(event, filesystem):
    """Lookup the parent folder in the filesystem content."""
    path = event.get('path', '')
    if not path:
        return None

    parts = path.split('/')
    if len(parts) <= 1:
        return None

    parent_path = '/'.join(parts[:-1]) or '/'
    return filesystem.get(parent_path)

