def _get_csrf_disabled_param():
    """Return the right param to disable CSRF depending on WTF-Form version.

    From Flask-WTF 0.14.0, `csrf_enabled` param has been deprecated in favor of
    `meta={csrf: True/False}`.
    """
    import pkg_resources
    try:
        version = pkg_resources.get_distribution("Flask-WTF").version
        major, minor, patch = map(int, version.split('.'))
        if major > 0 or (major == 0 and minor >= 14):
            return {"meta": {"csrf": False}}
    except (pkg_resources.DistributionNotFound, ValueError):
        pass
    return {"csrf_enabled": False}

