def enqueue_job(request, queue_index, job_id):
    """ Enqueue deferred jobs
    """
    queue = request.get('queues', [])
    if queue_index < len(queue):
        queue[queue_index].append(job_id)
    else:
        while len(queue) <= queue_index:
            queue.append([])
        queue[queue_index].append(job_id)
    request['queues'] = queue

