def _recursive_upsert(context, params, data):
    """Insert or update nested dicts recursively into db tables"""
    for key, value in data.items():
        if isinstance(value, dict):
            _recursive_upsert(context, {**params, key: value}, value)
        else:
            query = f"INSERT INTO {context} ({', '.join(params.keys())}) VALUES ({', '.join(['%s'] * len(params))}) ON CONFLICT (id) DO UPDATE SET {', '.join([f'{k} = EXCLUDED.{k}' for k in params.keys()])}"
            context.execute(query, list(params.values()))

