mgc_code:
def parse_res(res, src_ds_list=None, t_srs=None):
    """Parse arbitrary input res 

    Parameters
    ----------
    res : str or gdal.Dataset or filename or float
        Arbitrary input res 
    src_ds_list : list of gdal.Dataset objects, optional
        Needed if specifying 'first' or 'last'
    t_srs : osr.SpatialReference() object 
        Projection for res calculations, optional

    Returns
    -------
    res : float 
        Output resolution
        None if source resolution should be preserved
    """
    if res is None:
        return None
    if isinstance(res, (int, float)):
        return float(res)
    if isinstance(res, str):
        res_lower = res.lower()
        if res_lower == 'first' or res_lower == 'last':
            if src_ds_list is None or len(src_ds_list) == 0:
                raise ValueError("src_ds_list must be provided for 'first' or 'last' resolution")
            ds = src_ds_list[0] if res_lower == 'first' else src_ds_list[-1]
            return float(ds.GetGeoTransform()[1])
        try:
            return float(res)
        except ValueError:
            from osgeo import gdal
            ds = gdal.Open(res)
            if ds is None:
                raise FileNotFoundError(f"Could not open file {res}")
            return float(ds.GetGeoTransform()[1])
    try:
        return float(res.GetGeoTransform()[1])
    except AttributeError:
        raise TypeError("Unsupported type for res")

