mgc_code:
def fill_array(dstarr, order, r, g, b, a):
    """Fill array dstarr with a color value. order defines the color planes
    in the array.  (r, g, b, a) are expected to be in the range 0..1 and
    are scaled to the appropriate values.

    dstarr can be a 2D or 3D array.
    """
    import numpy as np

    # Determine the bit depth based on the array dtype
    if np.issubdtype(dstarr.dtype, np.integer):
        info = np.iinfo(dstarr.dtype)
        max_val = info.max
    else:
        max_val = 1.0

    # Map the order string to the provided color components
    color_map = {'r': r, 'g': g, 'b': b, 'a': a}

    # Handle 3D arrays (height, width, channels)
    if dstarr.ndim == 3:
        for i, char in enumerate(order):
            dstarr[:, :, i] = color_map[char] * max_val
    # Handle 2D arrays (single channel)
    elif dstarr.ndim == 2:
        # If 2D, we assume the array represents the first channel in 'order'
        dstarr[:] = color_map[order[0]] * max_val

