import subprocess

try:
    cmd = ['chkconfig', '--list', name]
    if runlevel is not None:
        cmd.append(str(runlevel))

    output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, universal_newlines=True)

    # chkconfig --list output typically contains "on" or "off" for runlevels
    # If runlevel is specified, we check the specific column; otherwise,
    # we check if any runlevel is 'on'.
    lines = output.splitlines()
    for line in lines:
        if name in line:
            parts = line.split()
            # The runlevel statuses are usually the last few columns
            statuses = [p for p in parts if p in ('on', 'off')]
            if runlevel is not None:
                # This is a simplification; actual chkconfig output mapping
                # depends on the specific OS version.
                return 'on' in statuses
            return any(s == 'on' for s in statuses)
    return False
except (subprocess.CalledProcessError, FileNotFoundError):
    return False

