mgc_code:
def _check_inputs(z, m):
    """Check inputs are arrays of same length or array and a scalar."""
    import numpy as np

    z = np.asanyarray(z)
    m = np.asanyarray(m)
    if m.ndim == 0:
        return z, m
    if z.shape != m.shape:
        raise ValueError("z and m must have the same shape or m must be a scalar.")
    return z, m

