def complement(self, alphabet):
        """
        Returns the complement of DFA
        Args:
            alphabet (list): The input alphabet
        Returns:
            None
        """
        new_states = set(self.states)
        for state in self.states:
            if state in self.accept_states:
                new_states.discard(state)

        for state in self.states:
            if state not in self.accept_states:
                new_states.add(state)

        self.accept_states = new_states

