def object_list(self):
        """
        Return this table's object_list, transformed (sorted, reversed,
        filtered, etc) according to its meta options.
        """
        objs = self.object_list
        meta = self._meta

        if hasattr(meta, 'ordering'):
            from django.db.models.query import QuerySet
            if isinstance(objs, QuerySet):
                objs = objs.order_by(*meta.ordering)
            else:
                for field in meta.ordering:
                    reverse = field.startswith('-')
                    attr = field[1:] if reverse else field
                    objs = sorted(objs, key=lambda x: getattr(x, attr), reverse=reverse)

        if getattr(meta, 'reversed', False):
            objs = reversed(objs)

        if hasattr(meta, 'filter_func') and callable(meta.filter_func):
            objs = filter(meta.filter_func, objs)

        return objs

