mgc_code:
def list_sig_ok(self, signature: str):
        """
        return if a signature is indeed a list and all objects are intact
        :param signature:
        :return:
        """
        if not signature.startswith('[') or not signature.endswith(']'):
            return False

        content = signature[1:-1]
        if not content:
            return True

        stack = 0
        in_quotes = False
        quote_char = ''

        for i, char in enumerate(content):
            if char in ("'", '"'):
                if not in_quotes:
                    in_quotes = True
                    quote_char = char
                elif char == quote_char:
                    in_quotes = False

            if not in_quotes:
                if char == '[':
                    stack += 1
                elif char == ']':
                    stack -= 1
                    if stack < 0:
                        return False

        return stack == 0

