mgc_code:
def is_resource_modified(
    environ, etag=None, data=None, last_modified=None, ignore_if_range=True
):
    """Convenience method for conditional requests.

    :param environ: the WSGI environment of the request to be checked.
    :param etag: the etag for the response for comparison.
    :param data: or alternatively the data of the response to automatically
                 generate an etag using :func:`generate_etag`.
    :param last_modified: an optional date of the last modification.
    :param ignore_if_range: If `False`, `If-Range` header will be taken into
                            account.
    :return: `True` if the resource was modified, otherwise `False`.
    """
    from wsgiref.util import request_uri
    from datetime import datetime
    import hashlib

    def get_header(name):
        return environ.get(f'HTTP_{name.upper().replace("-", "_")}')

    if data is not None and etag is None:
        etag = hashlib.md5(data).hexdigest()

    if_none_match = get_header('If-None-Match')
    if if_none_match:
        if etag and etag == if_none_match:
            return False
        if if_none_match == '*':
            return False

    if_modified_since = get_header('If-Modified-Since')
    if if_modified_since and last_modified:
        try:
            # Simple HTTP date parsing
            fmt = '%a, %d %b %Y %H:%M:%S GMT'
            ims_date = datetime.strptime(if_modified_since, fmt)
            if last_modified <= ims_date:
                return False
        except (ValueError, TypeError):
            pass

    if not ignore_if_range:
        if_range = get_header('If-Range')
        if if_range:
            if etag and etag != if_range:
                return True

    return True

