def getLeastUsedCell(self, c):
    """For the least used cell in a column"""
    counts = {}
    for row in range(self.size):
        val = self.board[row][c]
        if val != 0:
            counts[val] = counts.get(val, 0) + 1

    min_count = float('inf')
    least_used = None

    for num in range(1, self.size + 1):
        count = counts.get(num, 0)
        if count < min_count:
            min_count = count
            least_used = num

    return least_used

