mgc_code:
def stylesheet(self, fn=None, unit=CSS.rem, pt_per_em=None, decimals=2, font_factor=1/2., space_factor=1/20.):
        """create a CSS stylesheet in a Text document, using DOCX.stylemap(), above."""
        if pt_per_em is None:
            pt_per_em = 12.0

        styles = self.stylemap()
        lines = []

        for name, props in styles.items():
            selector = f".{name}" if not name.startswith('#') else name
            lines.append(f"{selector} {{")

            for prop, value in props.items():
                if isinstance(value, (int, float)):
                    if prop in ('font-size', 'margin', 'padding', 'line-height'):
                        # Convert points to rem
                        val_rem = (value / pt_per_em) / font_factor
                        lines.append(f"  {prop}: {val_rem:.{decimals}f}{unit};")
                    else:
                        lines.append(f"  {prop}: {value:.{decimals}f};")
                else:
                    lines.append(f"  {prop}: {value};")

            lines.append("}\n")

        css_text = "\n".join(lines)
        if fn:
            with open(fn, 'w') as f:
                f.write(css_text)
            return None
        return css_text

