mgc_code:
def client_end(request, socket, context):
    """
    Handles cleanup when a session ends for the given client triple.
    Sends unsubscribe and finish events, actually unsubscribes from
    any channels subscribed to, and removes the client triple from
    CLIENTS.
    """
    unsubscribe_event = {"type": "unsubscribe", "client": request}
    finish_event = {"type": "finish", "client": request}

    socket.send(unsubscribe_event)
    socket.send(finish_event)

    if request in CLIENTS:
        client_data = CLIENTS[request]
        if hasattr(client_data, 'subscriptions'):
            for channel in client_data.subscriptions:
                context.unsubscribe(request, channel)
        del CLIENTS[request]

