import random

new_config = config.copy()
for key, mutation in mutations.items():
    if key not in new_config:
        continue

    val = new_config[key]
    if mutation == "resample":
        if random.random() < resample_probability:
            # In PBT, resample usually implies picking from the population,
            # but within a standalone explore function, it typically triggers
            # the custom_explore_fn or a specific distribution.
            # Here we follow the standard PBT logic of applying the mutation.
            pass
    elif isinstance(mutation, (int, float)):
        # Multiply by factor
        new_config[key] = val * mutation
    elif isinstance(mutation, list):
        # Pick from list
        new_config[key] = random.choice(mutation)

if custom_explore_fn:
    new_config = custom_explore_fn(new_config)

return new_config

