def tree_to_str(root):
    """
    Returns a string representation of a decision tree with
    root node `root`.
    """
    if root is None:
        return ""
    if not hasattr(root, 'children') or not root.children:
        return str(root.value)

    parts = []
    for i, child in enumerate(root.children):
        parts.append(f"Child {i}: {tree_to_str(child)}")

    return f"Node({root.value}) -> {' | '.join(parts)}"

