mgc_code:
def _get_pkg_info(*packages, **kwargs):
    """
    Return list of package information. If 'packages' parameter is empty,
    then data about all installed packages will be returned.

    :param packages: Specified packages.
    :param failhard: Throw an exception if no packages found.
    :return:
    """
    import pkg_resources

    failhard = kwargs.get('failhard', False)
    installed_packages = {pkg.key: pkg for pkg in pkg_resources.working_set}

    if not packages:
        target_keys = installed_packages.keys()
    else:
        target_keys = [pkg.lower() for pkg in packages]

    results = []
    for key in target_keys:
        if key in installed_packages:
            pkg = installed_packages[key]
            results.append({
                'name': pkg.project_name,
                'version': pkg.version,
                'location': pkg.location
            })

    if failhard and not results:
        raise RuntimeError("No specified packages found.")

    return results

