def _parse_color(self, color):
        """Setup the color scheme"""
        if color.startswith('#'):
            color = tuple(int(color[i:i+2], 16) for i in (1, 3, 5))
        elif color.lower() == 'white':
            color = (255, 255, 255)
        elif color.lower() == 'black':
            color = (0, 0, 0)
        else:
            raise ValueError(f"Unsupported color string: {color}")
        return color

