mgc_code:
def sanitize_http_request_cookies(client, event):
    """
    Sanitizes http request cookies

    :param client: an ElasticAPM client
    :param event: a transaction or error event
    :return: The modified event
    """
    cookies = event.context.get('request', {}).get('cookies')
    if cookies and isinstance(cookies, dict):
        sanitized_cookies = {}
        for key, value in cookies.items():
            if key.lower() in ('sessionid', 'auth_token', 'access_token', 'csrf_token'):
                sanitized_cookies[key] = '[REDACTED]'
            else:
                sanitized_cookies[key] = value
        event.context['request']['cookies'] = sanitized_cookies
    return event

