@contextlib.contextmanager
def wrapper():
    try:
        yield
    except exception as e:
        actual_errno = getattr(e, 'errno', None)
        if actual_errno == errno:
            return
        raise AssertionError(
            msg_fmt.format(
                msg="wrong errno",
                exc_type=exception,
                exc_name=exception.__name__,
                expected_errno=errno,
                actual_errno=actual_errno
            ) if msg_fmt != "{msg}" else f"wrong errno: {errno} != {actual_errno}"
        )
    except Exception as e:
        raise AssertionError(
            msg_fmt.format(
                msg="wrong exception type",
                exc_type=exception,
                exc_name=exception.__name__,
                expected_errno=errno,
                actual_errno=getattr(e, 'errno', None)
            ) if msg_fmt != "{msg}" else f"wrong exception type: {type(e)} != {exception}"
        )
    else:
        raise AssertionError(
            msg_fmt.format(
                msg="no exception raised",
                exc_type=exception,
                exc_name=exception.__name__,
                expected_errno=errno,
                actual_errno=None
            ) if msg_fmt != "{msg}" else "no exception raised"
        )

return wrapper()

