mgc_code:
def check_nocycles(Adj, verbosity=2):
    """\
    Checks that there are no cycles in graph described by adjacancy matrix.

    Parameters
    ----------
    Adj (np.array): adjancancy matrix of dimension (dim, dim)

    Returns
    -------
    True if there is no cycle, False otherwise.
    """
    import numpy as np

    dim = Adj.shape[0]
    visited = np.zeros(dim, dtype=bool)
    rec_stack = np.zeros(dim, dtype=bool)

    def has_cycle(v):
        visited[v] = True
        rec_stack[v] = True
        for neighbor in np.where(Adj[v] != 0)[0]:
            if not visited[neighbor]:
                if has_cycle(neighbor):
                    return True
            elif rec_stack[neighbor]:
                return True
        rec_stack[v] = False
        return False

    for node in range(dim):
        if not visited[node]:
            if has_cycle(node):
                return False
    return True

