def fasta2bed(fastafile):
    """
    Alternative BED generation from FASTA file. Used for sanity check.
    """
    bed_lines = []
    current_chrom = None
    current_start = 0
    with open(fastafile, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('>'):
                if current_chrom is not None:
                    bed_lines.append(f"{current_chrom}\t{current_start}\t{current_start}\n")
                current_chrom = line[1:].split()[0]
                current_start = 0
            else:
                current_start += len(line)
        if current_chrom is not None:
            bed_lines.append(f"{current_chrom}\t{current_start}\t{current_start}\n")
    return bed_lines

