mgc_code:
def copy(self, only=None):
        """
        Returns a deep copy with all of the numpy arrays copied
        If only is a list of strings, i.e. ['f', 'v'], then only those properties will be copied
        """
        import copy as cp
        new_obj = cp.copy(self)
        if only is None:
            for key, value in self.__dict__.items():
                if hasattr(value, 'copy'):
                    new_obj.__dict__[key] = value.copy()
                else:
                    new_obj.__dict__[key] = cp.deepcopy(value)
        else:
            new_obj.__dict__ = {}
            for key in only:
                if hasattr(self, key):
                    value = getattr(self, key)
                    if hasattr(value, 'copy'):
                        new_obj.__dict__[key] = value.copy()
                    else:
                        new_obj.__dict__[key] = cp.deepcopy(value)
        return new_obj

