def list(self, **kwargs):
        """Retrieve a list of objects.

        Args:
            all (bool): If True, return all the items, without pagination
            per_page (int): Number of items to retrieve per request
            page (int): ID of the page to return (starts with page 1)
            as_list (bool): If set to False and no pagination option is
                defined, return a generator instead of a list
            **kwargs: Extra options to send to the server (e.g. sudo)

        Returns:
            list: The list of objects, or a generator if `as_list` is False

        Raises:
            GitlabAuthenticationError: If authentication is not correct
            GitlabListError: If the server cannot perform the request
        """
        all_items = kwargs.pop('all', False)
        per_page = kwargs.pop('per_page', None)
        page = kwargs.pop('page', None)
        as_list = kwargs.pop('as_list', True)

        if all_items:
            params = {'per_page': 100}
            results = []
            while True:
                page_data = self._request('GET', self.path, **kwargs, **params)
                results.extend(page_data)
                if len(page_data) < 100:
                    break
                params['page'] = params.get('page', 1) + 1
            return results

        if per_page or page:
            params = {'per_page': per_page, 'page': page}
            return self._request('GET', self.path, **kwargs, **params)

        if not as_list:
            def generator():
                params = {'per_page': 100, 'page': 1}
                while True:
                    page_data = self._request('GET', self.path, **kwargs, **params)
                    if not page_data:
                        break
                    for item in page_data:
                        yield item
                    if len(page_data) < 100:
                        break
                    params['page'] += 1
            return generator()

        return self._request('GET', self.path, **kwargs)

