mgc_code:
def scoped(self, func):
        """
        Decorator to switch scopes.

        """
        from functools import wraps

        @wraps(func)
        def wrapper(*args, **kwargs):
            old_scope = self.scope
            self.scope = func.__name__
            try:
                return func(*args, **kwargs)
            finally:
                self.scope = old_scope
        return wrapper

