raw_output:
import socket
import os

if pid is None:
    pid = os.getpid()

if portserver_address is None:
    portserver_address = os.environ.get('PORTSERVER_ADDRESS')

if portserver_address:
    try:
        if portserver_address.startswith('@'):
            family = socket.AF_UNIX
            address = portserver_address[1:]
            # Abstract namespace sockets start with \0
            address = '\0' + address
        elif hasattr(socket, 'AF_UNIX') and not any(char.isdigit() for char in portserver_address.split(':')[-1]):
            family = socket.AF_UNIX
            address = portserver_address
        else:
            family = socket.AF_INET
            address = tuple(portserver_address.split(':'))
            if len(address) == 2:
                address = (address[0], int(address[1]))

        with socket.socket(family, socket.SOCK_STREAM) as s:
            s.settimeout(2.0)
            s.connect(address if family == socket.AF_UNIX else address)
            # Protocol: send "PICK <pid>", receive "<port>"
            s.sendall(f"PICK {pid}\n".encode('utf-8'))
            response = s.recv(1024).decode('utf-8').strip()
            if response and response.isdigit():
                return int(response)
    except Exception:
        pass

# Fallback: Local search for an unused port
for _ in range(100):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.bind(('', 0))
            port = s.getsockname()[1]

        # Verify UDP is also free
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as u:
            u.bind(('', port))

        return port
    except socket.error:
        continue

raise NoFreePortFoundError("No free port could be found.")

