def properties(self, rel_path=None):
        """ Return a dictionary with all svn-properties associated with a
            relative path.
        :param rel_path: relative path in the svn repo to query the
                         properties from
        :returns: a dictionary with the property name as key and the content
                  as value
        """
        if rel_path is None:
            rel_path = '.'

        import subprocess
        try:
            process = subprocess.Popen(
                ['svn', 'propget', '--all', rel_path],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )
            stdout, stderr = process.communicate()

            if process.returncode != 0:
                return {}

            props = {}
            current_key = None
            for line in stdout.splitlines():
                if line.startswith('Propname: '):
                    current_key = line[9:].strip()
                    props[current_key] = []
                elif current_key:
                    props[current_key].append(line)

            return {k: '\n'.join(v) for k, v in props.items()}
        except Exception:
            return {}

