def handle_dims(opts):
    """
    Script option handling.
    """
    dims = opts.get('dims', None)
    if dims is None:
        return None
    if isinstance(dims, int):
        return (dims,) * dims
    if isinstance(dims, (list, tuple)):
        return tuple(dims)
    raise TypeError("dims must be an int or a sequence of ints")

