def read_http_header(sock):
    """Read HTTP header from socket, return header and rest of data."""
    data = b""
    while b"\r\n\r\n" not in data:
        chunk = sock.recv(4096)
        if not chunk:
            break
        data += chunk

    if b"\r\n\r\n" in data:
        header, body = data.split(b"\r\n\r\n", 1)
        return header, body
    return data, b""

