def parse_doc(f, ctx=None, overwrite=False):
    """ Accepts an open file or a list of lines. """
    if ctx is None:
        ctx = {}

    lines = f.readlines() if hasattr(f, 'readlines') else f

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if overwrite or key not in ctx:
                ctx[key] = value

    return ctx

