def _fetch_recursive(res_id, current_level):
    if current_level >= recurse_max_level:
        return self.get_resource(res_id)

    resource = self.get_resource(res_id)
    children_ids = self.get_resource_children_ids(res_id)

    if 'search_pattern' in kwargs:
        children_ids = self.find_collection_ids(kwargs['search_pattern'], parent_id=res_id)

    children_data = []
    for child_id in children_ids:
        children_data.append(_fetch_recursive(child_id, current_level + 1))

    if sort_by:
        children_data.sort(key=lambda x: x.get(sort_by, ''), reverse=sort_data.get('reverse', False))

    resource['children'] = children_data
    return resource

