    data = np.asanyarray(data)

    if origin is None:
        origin = np.zeros(data.ndim)
    if spacing is None:
        spacing = np.ones(data.ndim)
    if direction is None:
        direction = np.eye(data.ndim)

    from ants.core import ANTsImage
    return ANTsImage(data, origin=origin, spacing=spacing, direction=direction, 
                     has_components=has_components, is_rgb=is_rgb)

