def _psi(self,m):
        """\psi(m) = -\int_m^\infty d m^2 \rho(m^2)"""
        import numpy as np
        from scipy.integrate import quad

        def rho(m_sq):
            # This is a placeholder for the spectral density function.
            # In a real implementation, this would be defined based on the specific model.
            return np.exp(-m_sq)

        result, _ = quad(rho, m**2, np.inf)
        return -result

