def wrapper(func):
    def wait_handler(*args, **kwargs):
        import time

        poll_freq = 0.5
        end_time = time.time() + timeout
        while time.time() <= end_time:
            try:
                value = func(*args, **kwargs)
                if value:
                    return value
            except exc as e:
                LOGGER.debug(e)
                pass  # continue

            time.sleep(poll_freq)
            poll_freq *= 1.25
        raise RuntimeError(msg)
    return wait_handler
return wrapper

