mgc_code:
def wait(msg='', exceptions=None, timeout=10):
    """
    Decorator to handle generic waiting situations.

    Will handle StaleElementReferenceErrors.

    :param msg: Error message
    :param exceptions: Extra exceptions to handle
    :param timeout: time to keep trying (default: 10 seconds)
    :return: the result of the decorated function
    """
    import time
    from selenium.common.exceptions import StaleElementReferenceException

    def decorator(func):
        def wrapper(*args, **kwargs):
            start_time = time.time()
            err_list = [StaleElementReferenceException]
            if exceptions:
                if isinstance(exceptions, Exception):
                    err_list.append(exceptions)
                else:
                    err_list.extend(exceptions)

            while True:
                try:
                    return func(*args, **kwargs)
                except tuple(err_list) as e:
                    if time.time() - start_time > timeout:
                        raise RuntimeError(f"{msg}: {str(e)}") from e
                    time.sleep(0.5)
        return wrapper
    return decorator

