mgc_code:
def incomplete_dir(dirname):
  """Create temporary dir for dirname and rename on exit."""
  import tempfile
  import os
  import atexit

  tmp_dir = tempfile.mkdtemp(dir=os.path.dirname(dirname))

  def rename_on_exit():
      try:
          os.rename(tmp_dir, dirname)
      except OSError:
          pass

  atexit.register(rename_on_exit)
  return tmp_dir

