def factorize(self,A):
        """
        Factorizes A.

        Parameters
        ----------
        A : matrix
           For symmetric systems, should contain only lower diagonal part.
        """
        n = A.shape[0]
        for i in range(n):
            for j in range(i + 1):
                s = sum(A[i, k] * A[j, k] for k in range(j))
                if i == j:
                    A[i, i] = (A[i, i] - s)**0.5
                else:
                    A[i, j] = (A[i, j] - s) / A[j, j]

