dvs = []
dvsnoexp = []
maxcount = 5

for dv in regime.derived_variables:
    if dv.expression_tree == None:
        dvsnoexp.append(dv.name)
    else:
        dvs.append(dv.name)

for dv in regime.conditional_derived_variables:
    if len(dv.cases) == 0:
        dvsnoexp.append(dv.name)
    else:
        dvs.append(dv.name)


count = maxcount

while count > 0 and dvs != []:
