mgc_code:
def order_derived_variables(regime):
    """
    Finds ordering of derived_variables.

    @param regime: Dynamics Regime containing derived variables.
    @type regime: lems.model.dynamics.regime

    @return: Returns ordered list of derived variables.
    @rtype: list(string)

    @raise SimBuildError: Raised when a proper ordering of derived
    variables could not be found.
    """
    from collections import deque
    from lems.model.dynamics import SimBuildError

    derived = regime.derived_variables
    adj = {var: [] for var in derived}
    in_degree = {var: 0 for var in derived}

    for var, expr in derived.items():
        for dep in expr.dependencies:
            if dep in derived:
                adj[dep].append(var)
                in_degree[var] += 1

    queue = deque([v for v in derived if in_degree[v] == 0])
    ordered = []

    while queue:
        u = queue.popleft()
        ordered.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(ordered) != len(derived):
        raise SimBuildError("Circular dependency detected in derived variables.")

    return ordered

