mgc_code:
def packages(
    state, host, packages=None,
    present=True, latest=False, update=False, clean=False,
):
    """
    Install/remove/update yum packages & updates.

    + packages: list of packages to ensure
    + present: whether the packages should be installed
    + latest: whether to upgrade packages without a specified version
    + update: run yum update
    + clean: run yum clean

    Versions:
        Package versions can be pinned like yum: ``<pkg>-<version>``
    """
    if clean:
        state.run_command("yum clean all", host=host)

    if update:
        state.run_command("yum update -y", host=host)

    if packages:
        for pkg in packages:
            if present:
                cmd = f"yum install -y {pkg}"
                if latest:
                    cmd = f"yum update -y {pkg}"
                state.run_command(cmd, host=host)
            else:
                state.run_command(f"yum remove -y {pkg}", host=host)

