mgc_code:
def config_diff(args):
    """Compare method configuration definitions across workspaces. Ignores
       methodConfigVersion if the verbose argument is not set"""
    verbose = args.get('verbose', False)
    workspaces = args.get('workspaces', {})
    diffs = {}

    all_methods = set()
    for ws_name, config in workspaces.items():
        all_methods.update(config.keys())

    for method in all_methods:
        method_diffs = {}
        base_config = None
        base_ws = None

        for ws_name, config in workspaces.items():
            current_config = config.get(method, {})
            if base_config is None:
                base_config = current_config
                base_ws = ws_name
                continue

            changes = {}
            all_keys = set(base_config.keys()) | set(current_config.keys())
            for key in all_keys:
                if key == 'methodConfigVersion' and not verbose:
                    continue

                val1 = base_config.get(key)
                val2 = current_config.get(key)
                if val1 != val2:
                    changes[key] = {'from': val1, 'to': val2}

            if changes:
                method_diffs[ws_name] = changes

        if method_diffs:
            diffs[method] = method_diffs

    return diffs

