import numpy as np

if ignore_order:
    if all_close:
        # For each element in row1, check if there is a close match in row2
        # that hasn't been used yet.
        matched = np.zeros(len(row2), dtype=bool)
        for val in row1:
            close_indices = np.where(np.isclose(row2, val))[0]
            available = close_indices[~matched[close_indices]]
            if available.size == 0:
                return False
            matched[available[0]] = True
        row2.mask[:] = True
        return True
    else:
        # Exact match regardless of order
        sorted1 = np.sort(row1)
        sorted2 = np.sort(row2)
        if np.array_equal(sorted1, sorted2):
            row2.mask[:] = True
            return True
        return False
else:
    # Order matters
    if all_close:
        if np.all(np.isclose(row1, row2)):
            row2.mask[:] = True
            return True
    else:
        if np.array_equal(row1, row2):
            row2.mask[:] = True
            return True
    return False

