if merge_type is None:
    merge_type = type(self)

if not hasattr(self, 'dims'):
    return self

dims = list(self.dims)
if drop_constant:
    dims = [d for d in dims if len(self[d]) > 1]

for d in drop:
    if d in dims:
        dims.remove(d)

if not dims:
    return self

merged = merge_type()
for key, value in self.items():
    # Filter out dropped dimensions from the key
    filtered_key = tuple(v for k, v in zip(self.dims, key) if k in dims)

    if hasattr(value, 'collate'):
        collated_value = value.collate(merge_type, drop, drop_constant)
    else:
        collated_value = value

    merged[filtered_key] = collated_value

return merged

