    if term.endswith("'s"):
        stripped_term = term[:-2]
    else:
        stripped_term = term

    single_term = singularize(stripped_term)

    if term in COMMON_TERMS or stripped_term in COMMON_TERMS or single_term in COMMON_TERMS:
        continue

    output.append(single_term)

return output

