mgc_code:
def metar(data: MetarData, units: Units) -> str:
    """
    Convert MetarData into a string for text-to-speech
    """
    parts = []
    if data.station:
        parts.append(f"Station {data.station}")
    if data.wind_dir:
        parts.append(f"Wind from {data.wind_dir} degrees")
    if data.wind_speed:
        speed = data.wind_speed if units.speed == "knots" else data.wind_speed * 0.514444
        parts.append(f"at {speed:.1f} {units.speed}")
    if data.visibility:
        vis = data.visibility if units.distance == "miles" else data.visibility * 0.621371
        parts.append(f"Visibility {vis:.1f} {units.distance}")
    if data.temp:
        temp = data.temp if units.temp == "celsius" else (data.temp * 9/5) + 32
        parts.append(f"Temperature {temp:.1f} degrees {units.temp}")
    if data.dewpoint:
        dp = data.dewpoint if units.temp == "celsius" else (data.dewpoint * 9/5) + 32
        parts.append(f"Dewpoint {dp:.1f} degrees {units.temp}")
    if data.altimeter:
        parts.append(f"Altimeter {data.altimeter} hectopascals")
    if data.conditions:
        parts.append(f"Conditions {data.conditions}")
    return ". ".join(parts) + "." if parts else "No weather data available."

