def _copy_margin(self, cli, lazy_screen, new_screen, write_position, move_x, width):
        """
        Copy characters from the margin screen to the real screen.
        """
        for y in range(lazy_screen.height):
            for x in range(width):
                char = lazy_screen.get_char(x, y)
                new_screen.set_char(write_position[0] + move_x + x, write_position[1] + y, char)

