def _load_tasks(self, tasks, vars={}, additional_conditions=[]):
        """ handle task and handler include statements """
        loaded_tasks = {}
        for task_name, task_data in tasks.items():
            if isinstance(task_data, str) and task_data.startswith('include '):
                include_path = task_data[8:].strip()
                # This assumes a helper method _read_file exists to load YAML/JSON
                included = self._read_file(include_path)
                # Recursively load included tasks
                loaded_tasks.update(self._load_tasks(included, vars, additional_conditions))
            else:
                # Process task data with variables and conditions
                processed_data = self._process_task_data(task_data, vars, additional_conditions)
                loaded_tasks[task_name] = processed_data
        return loaded_tasks

