def process_file(vcs, commit, force, gitlint_config, file_data):
    """Lint the file

    Returns:
      The results from the linter.
    """
    if not force and not commit:
        return []

    results = []
    # This is a generic implementation of a linting process
    # based on the provided parameters.
    if gitlint_config:
        # Simulate linting logic using the config and file data
        for line_num, line in enumerate(file_data.splitlines(), 1):
            if not line.strip():
                continue
            # Example rule: check for line length if configured
            max_len = gitlint_config.get('max_line_length', 120)
            if len(line) > max_len:
                results.append({
                    'line': line_num,
                    'column': max_len,
                    'message': f'Line too long ({len(line)} > {max_len})',
                    'file': vcs
                })

    return results

