mgc_code:
def get_missing_flags(conf, atom, flags):
    """
    Find out which of the given flags are currently not set.
    CLI Example:

    .. code-block:: bash

        salt '*' portage_config.get_missing_flags use salt "['ldap', '-libvirt', 'openssl']"
    """
    missing = []
    for flag in flags:
        if flag.startswith('-'):
            # If flag starts with '-', it's a 'must be absent' check.
            # If it is present, it's not 'missing' from the desired state.
            if conf.get(flag[1:], False):
                continue
        else:
            # If flag doesn't start with '-', it's a 'must be present' check.
            if conf.get(flag, False):
                continue
        missing.append(flag)
    return missing

