def get_all_files_in_range(dirname, starttime, endtime, pad=64):
    """Returns all files in dirname and all its subdirectories whose
    names indicate that they contain segments in the range starttime
    to endtime"""
    import os
    import re

    files = []
    # Regex to find numbers in filenames to identify time segments
    pattern = re.compile(r'(\d+)')

    for root, _, filenames in os.walk(dirname):
        for filename in filenames:
            matches = pattern.findall(filename)
            if not matches:
                continue

            # Assume the first number found is the timestamp/segment ID
            try:
                file_time = int(matches[0])
                if starttime <= file_time <= endtime:
                    files.append(os.path.join(root, filename))
            except ValueError:
                continue

    return files

