def get_alter_table_sql(self, diff):
        """
        Get the ALTER TABLE SQL statement

        :param diff: The table diff
        :type diff: eloquent.dbal.table_diff.TableDiff

        :rtype: list
        """
        if diff.rename_from:
            sql.append(f"ALTER TABLE `{diff.rename_from}` RENAME TO `{diff.table}`")

        for add in diff.added:
            sql.append(f"ALTER TABLE `{diff.table}` ADD {add.column_sql}")

        for drop in diff.dropped:
            sql.append(f"ALTER TABLE `{diff.table}` DROP COLUMN `{drop.column}`")

        for change in diff.changed:
            sql.append(f"ALTER TABLE `{diff.table}` MODIFY {change.column_sql}")

        return sql

