mgc_code:
def _initApplicationList(self):
        """Query Asterisk Manager Interface to initialize internal list of 
        available applications.

        CLI Command - core show applications

        """
        self.applications = []
        response = self.ami.send_command('core show applications')
        if response:
            for line in response.splitlines():
                line = line.strip()
                if line and not line.startswith('Application') and not line.startswith('---'):
                    parts = line.split(maxsplit=1)
                    if parts:
                        app_name = parts[0]
                        description = parts[1] if len(parts) > 1 else ""
                        self.applications.append({'name': app_name, 'description': description})

