def layers_distance(list_a, list_b):
    """The distance between the layers of two neural networks."""
    len_a = len(list_a)
    len_b = len(list_b)
    f = np.zeros((len_a + 1, len_b + 1))
    f[-1][-1] = 0
    for i in range(-1, len_a):
        f[i][-1] = i + 1
    for j in range(-1, len_b):
        f[-1][j] = j + 1
    for i in range(len_a):
        for j in range(len_b):
            f[i][j] = min(
                f[i][j - 1] + 1,
                f[i - 1][j] + 1,
                f[i - 1][j - 1] + layer_distance(list_a[i], list_b[j]),
            )
    return f[len_a - 1][len_b - 1]

mgc_code:
def layers_distance(list_a, list_b):
    """The distance between the layers of two neural networks."""
    if len(list_a) != len(list_b):
        raise ValueError("Networks must have the same number of layers")

    total_distance = 0
    for layer_a, layer_b in zip(list_a, list_b):
        total_distance += sum((a - b) ** 2 for a, b in zip(layer_a, layer_b))

    return total_distance ** 0.5

