mgc_code:
def add_fact(self, fact, temporary_activity = False):
        """Add fact. activity name can use the
        `[-]start_time[-end_time] activity@category, description #tag1 #tag2`
        syntax, or params can be stated explicitly.
        Params will take precedence over the derived values.
        start_time defaults to current moment.
        """
        import re
        from datetime import datetime

        if isinstance(fact, dict):
            params = fact
        else:
            params = {}
            pattern = r"^(?:\[(.*?)\])?(?:\[(.*?)\])?\s*([^,@#\s]+)(?:@([^,@#\s]+))?(?:,\s*([^#]+))?(?:\s*(#\S+.*))?$"
            match = re.match(pattern, fact)
            if match:
                start, end, activity, category, desc, tags = match.groups()
                if start: params['start_time'] = start
                if end: params['end_time'] = end
                if activity: params['activity'] = activity
                if category: params['category'] = category
                if desc: params['description'] = desc.strip()
                if tags: params['tags'] = tags.strip().split()
            else:
                params['description'] = fact

        if 'start_time' not in params:
            params['start_time'] = datetime.now().isoformat()

        if temporary_activity:
            params['temporary'] = True

        self.facts.append(params)

