def _create_skeleton_3(pc, l, num_section):
    """
    Bottom level: {"measurement": [], "model": [{summary, distributions, ensemble}]}
    Fill in measurement and model tables with N number of EMPTY meas, summary, ensemble, and distributions.
    :param str pc: Paleo or Chron "mode"
    :param list l:
    :param dict num_section:
    :return dict:
    """
    skeleton = {"measurement": [], "model": []}
    n_meas = num_section.get("measurement", 0)
    n_model = num_section.get("model", 0)

    for _ in range(n_meas):
        skeleton["measurement"].append({})

    for _ in range(n_model):
        skeleton["model"].append({
            "summary": [],
            "distributions": [],
            "ensemble": []
        })

    return skeleton

def hms_to_seconds(time_string):
    """
    Converts string 'hh:mm:ss.ssssss' as a float
    """
    h, m, s = time_string.split(':')
    return int(h) * 3600 + int(m) * 60 + float(s)

