def _expr2sat(ex, litmap): # pragma: no cover
    """Convert an expression to a DIMACS SAT string."""
    if isinstance(ex, Literal):
        return str(litmap[ex])
    elif isinstance(ex, NotOp):
        return "-(" + _expr2sat(ex.x, litmap) + ")"
    elif isinstance(ex, OrOp):
        return "+(" + " ".join(_expr2sat(x, litmap)
                               for x in ex.xs) + ")"
    elif isinstance(ex, AndOp):
        return "*(" + " ".join(_expr2sat(x, litmap)
                               for x in ex.xs) + ")"
    elif isinstance(ex, XorOp):
        return ("xor(" + " ".join(_expr2sat(x, litmap)
                                  for x in ex.xs) + ")")
    elif isinstance(ex, EqualOp):
        return "=(" + " ".join(_expr2sat(x, litmap)
                               for x in ex.xs) + ")"
    else:
        fstr = ("expected ex to be a Literal or Not/Or/And/Xor/Equal op, "
                "got {0.__name__}")
        raise ValueError(fstr.format(type(ex)))

solution:
scanner_object = pysigscan.scanner()

for format_specification in specification_store.specifications:
  for signature in format_specification.signatures:
    pattern_offset = signature.offset

    if pattern_offset is None:
      signature_flags = pysigscan.signature_flags.NO_OFFSET
    elif pattern_offset < 0:
      pattern_offset *= -1
      signature_flags = pysigscan.signature_flags.RELATIVE_FROM_END
    else:
      signature_flags = pysigscan.signature_flags.RELATIVE_FROM_START

    scanner_object.add_signature(
        signature.identifier, pattern_offset, signature.pattern,
        signature_flags)

return scanner_object

