def receive_data_chunk(self, raw_data, start):
        """
        Over-ridden method to circumvent the worker timeouts on large uploads.
        """
        self.buffer = getattr(self, 'buffer', b'')
        self.buffer += raw_data
        self.last_received_time = time.time()
        if start == 0:
            self.expected_size = self.get_expected_size()

        if len(self.buffer) >= self.expected_size:
            return self.process_complete_data(self.buffer)
        return None

