mgc_code:
def read_tree_nexus(nexus):
    """Read a tree from a Nexus string or file

    Args:
        ``nexus`` (``str``): Either a Nexus string or the path to a Nexus file (plain-text or gzipped)

    Returns:
        ``dict`` of ``Tree``: A dictionary of the trees represented by ``nexus``, where keys are tree names (``str``) and values are ``Tree`` objects
    """
    import gzip
    from Bio import Phylo
    from io import StringIO

    if hasattr(nexus, 'read'):
        handle = nexus
    else:
        try:
            with open(nexus, 'r') as f:
                content = f.read()
                handle = StringIO(content)
        except (OSError, IOError):
            try:
                with gzip.open(nexus, 'rt') as f:
                    content = f.read()
                    handle = StringIO(content)
            except (OSError, IOError):
                handle = StringIO(nexus)

    trees = {}
    while True:
        try:
            tree = Phylo.read(handle, "nexus")
            name = getattr(tree.root, 'name', 'unknown')
            trees[name] = tree
        except Exception:
            break
    return trees

