def _merge_by_type(lhs, rhs, type_):
    """Helper for '_merge_chunk'."""
    res = []
    i, j = 0, 0
    while i < len(lhs) and j < len(rhs):
        if lhs[i][0] == type_ and rhs[j][0] == type_:
            if lhs[i][1] < rhs[j][1]:
                res.append(lhs[i])
                i += 1
            else:
                res.append(rhs[j])
                j += 1
        elif lhs[i][0] == type_:
            res.append(lhs[i])
            i += 1
        elif rhs[j][0] == type_:
            res.append(rhs[j])
            j += 1
        else:
            # This case depends on the broader context of _merge_chunk,
            # but typically we advance the pointer of the non-matching type.
            if lhs[i][0] != type_ and (j >= len(rhs) or rhs[j][0] != type_):
                i += 1
            else:
                j += 1
    res.extend([x for x in lhs[i:] if x[0] == type_])
    res.extend([x for x in rhs[j:] if x[0] == type_])
    return res

