mgc_code:
def _write_strain_functional_genes(self, strain_id, ref_functional_genes, orth_matrix, force_rerun=False):
        """Create strain functional genes json file"""
        import json
        import os

        output_path = os.path.join(self.output_dir, f"{strain_id}_functional_genes.json")
        if not force_rerun and os.path.exists(output_path):
            with open(output_path, 'r') as f:
                return json.load(f)

        strain_functional_genes = {}
        for gene, ref_ids in ref_functional_genes.items():
            strain_genes = []
            for ref_id in ref_ids:
                if ref_id in orth_matrix and strain_id in orth_matrix[ref_id]:
                    strain_genes.extend(orth_matrix[ref_id][strain_id])
            if strain_genes:
                strain_functional_genes[gene] = list(set(strain_genes))

        with open(output_path, 'w') as f:
            json.dump(strain_functional_genes, f, indent=4)

        return strain_functional_genes

