def filterTs(ts, expressions):
    """
    Create a new time series that only contains entries that match the given expression.

    | Example:
    | D = lipd.loadLipd()
    | ts = lipd.extractTs(D)
    | new_ts = filterTs(ts, "archiveType == marine sediment")
    | new_ts = filterTs(ts, ["paleoData_variableName == sst", "archiveType == marine sediment"])
    | Expressions should use underscores to denote data nesting.
    | Ex: paleoData_hasResolution_hasMedian or

    :param list OR str expressions: Expressions
    :param list ts:                 Time series
    :return list new_ts:            Filtered time series that matches the expression
    """
    if isinstance(expressions, str):
        expressions = [expressions]

    filtered_ts = []
    for entry in ts:
        match_all = True
        for expr in expressions:
            # Split expression into left-hand side, operator, and right-hand side
            # Supports '==', '!=', '>', '<', '>=', '<='
            import re
            parts = re.split(r'\s*(==|!=|>=|<=|>|<)\s*', expr)
            if len(parts) < 3:
                continue

            key, op, val = parts[0], parts[1], parts[2]

            # Resolve nested keys (e.g., paleoData_variableName)
            current_val = entry
            for k in key.split('_'):
                if isinstance(current_val, dict) and k in current_val:
                    current_val = current_val[k]
                else:
                    current_val = None
                    break

            # Clean value (remove quotes if present)
            val = val.strip("'\"")

            # Evaluate condition
            try:
                if op == '==':
                    condition = (str(current_val) == val)
                elif op == '!=':
                    condition = (str(current_val) != val)
                elif op == '>':
                    condition = (float(current_val) > float(val))
                elif op == '<':
                    condition = (float(current_val) < float(val))
                elif op == '>=':
                    condition = (float(current_val) >= float(val))
                elif op == '<=':
                    condition = (float(current_val) <= float(val))
                else:
                    condition = False
            except (ValueError, TypeError):
                condition = False

            if not condition:
                match_all = False
                break

        if match_all:
            filtered_ts.append(entry)

    return filtered_ts

