def check(self, topic, value):
        """ Checking the value if it fits into the given specification """
        if topic not in self.specifications:
            return False

        spec = self.specifications[topic]
        if callable(spec):
            return spec(value)

        if isinstance(spec, list):
            return value in spec

        return value == spec

