        if cidr_ip:
            self.connection.authorizeSecurityGroupIngress(
                GroupId=self.groupId,
                IpPermissions=[{
                    'IpProtocol': 'tcp',
                    'FromPort': self.port,
                    'ToPort': self.port,
                    'IpRanges': [{'CidrIp': cidr_ip}]
                }]
            )
            return True
        elif ec2_group:
            self.connection.authorizeSecurityGroupIngress(
                GroupId=self.groupId,
                IpPermissions=[{
                    'IpProtocol': 'tcp',
                    'FromPort': self.port,
                    'ToPort': self.port,
                    'UserIdGroupPairs': [{'GroupId': ec2_group.id}]
                }]
            )
            return True
        return False

