def cache(cls, id):
        """return the number of query cache for the last 24H"""
        sampler = {'unit': 'days', 'value': 1, 'function': 'sum'}
        query = 'webacc.requests.cache.all'
        metrics = Metric.query(id, 60 * 60 * 24, query, 'paas', sampler)

        cache = {'hit': 0, 'miss': 0, 'not': 0, 'pass': 0}
        for metric in metrics:
            what = metric['cache'].pop()
            for point in metric['points']:
                value = point.get('value', 0)
                cache[what] += value
        return cache

mgc_code:
def cache(cls, id):
        """return the number of query cache for the last 24H"""
        import time
        from collections import deque

        if not hasattr(cls, '_query_cache_history'):
            cls._query_cache_history = {}

        now = time.time()
        day_in_seconds = 24 * 60 * 60

        if id not in cls._query_cache_history:
            cls._query_cache_history[id] = deque()

        history = cls._query_cache_history[id]
        while history and history[0] < now - day_in_seconds:
            history.popleft()

        return len(history)

