def place_visual(self):
        """Places visual objects randomly until no collisions or max iterations hit."""
        import random
        max_iterations = 1000
        for _ in range(max_iterations):
            collision = False
            for obj in self.visual_objects:
                obj.randomize_position()
                for other in self.visual_objects:
                    if obj is not other and obj.collides_with(other):
                        collision = True
                        break
                if collision:
                    break
            if not collision:
                break

