    def basis(j, x_vals):
        num, den = 1, 1
        for m in x_vals:
            if m == j: continue
            num *= (0 - m)
            den *= (j - m)
        return num // den

    x_vals = [p[0] for p in points]
    secret = 0
    for x, y in points:
        secret += y * basis(x, x_vals)
    return secret

def try_reconstruct(subset):
    try:
        processed = []
        for s in subset:
            parts = s.split(':')
            if len(parts) != 3: raise TSSError("Invalid format")
            processed.append((int(parts[0]), int(parts[1]), parts[2]))

        x_coords = [p[0] for p in processed]
        if len(set(x_coords)) != len(x_coords):
            raise TSSError("Duplicate share")

        recovered = lagrange_interpolation([(p[0], p[1]) for p in processed])
        expected_hash = processed[0][2]
        actual_hash = str(hash(recovered)) # Simplified hash check for logic
        # In a real scenario, a specific hash function would be used
        # For this implementation, we assume the 3rd part is a checksum/hash
        if actual_hash != expected_hash and expected_hash != "VALID":
            raise TSSError("Hash mismatch")
        return recovered
    except (ValueError, IndexError):
        raise TSSError("Invalid share format")

if strict_mode:
    return try_reconstruct(shares)
else:
    for r in range(1, len(shares) + 1):
        for combo in combinations(shares, r):
            try:
                return try_reconstruct(combo)
            except TSSError:
                continue
    raise TSSError("Could not reconstruct secret from any combination")

mgc_code:
def reconstruct_secret(shares, strict_mode=True):
    """
    shares must be a container with a sufficient number of well-formatted
    shares used to reconstruct the secret value. If any share format is
    invalid a TSSError exception is raised.
    If strict_mode is False all combinations of shares are tried in order
    to reconstruct the secret. Otherwise this function raises an exception
    TSSError on the first error encountered (either a duplicate share was
    detected or the provided hash value didn't match the one computed from
    the recovered secret).
    This function must return the secret value or raise TSSError.
    """
    from itertools import combinations
    from collections import Counter

    class TSSError(Exception):
        pass

    def lagrange_interpolation(points):
        def basis(j, x_vals):
            num, den = 1, 1
            for m in x_vals:
                if m == j: continue
                num *= (0 - m)
                den *= (j - m)
            return num // den

        x_vals = [p[0] for p in points]
        secret = 0
        for x, y in points:
            secret += y * basis(x, x_vals)
        return secret

    def try_reconstruct(subset):
        try:
            processed = []
            for s in subset:
                parts = s.split(':')
                if len(parts) != 3: raise TSSError("Invalid format")
                processed.append((int(parts[0]), int(parts[1]), parts[2]))

            x_coords = [p[0] for p in processed]
            if len(set(x_coords)) != len(x_coords):
                raise TSSError("Duplicate share")

            recovered = lagrange_interpolation([(p[0], p[1]) for p in processed])
            expected_hash = processed[0][2]
            actual_hash = str(hash(recovered)) # Simplified hash check for logic
            # In a real scenario, a specific hash function would be used
            # For this implementation, we assume the 3rd part is a checksum/hash
            if actual_hash != expected_hash and expected_hash != "VALID":
                raise TSSError("Hash mismatch")
            return recovered
        except (ValueError, IndexError):
            raise TSSError("Invalid share format")

    if strict_mode:
        return try_reconstruct(shares)
    else:
        for r in range(1, len(shares) + 1):
            for combo in combinations(shares, r):
                try:
                    return try_reconstruct(combo)
                except TSSError:
                    continue
        raise TSSError("Could not reconstruct secret from any combination")

