def control(self):
        """
        control    : 'if' ctrl_exp block ('elif' ctrl_exp block)* ('else' block)
        """
        node = {'type': 'IfStatement', 'if': (self.consume('if'), self.expression(), self.block())}
        node['elifs'] = []
        while self.peek('elif'):
            self.consume('elif')
            node['elifs'].append((self.expression(), self.block()))
        if self.peek('else'):
            self.consume('else')
            node['else'] = self.block()
        return node

