def parse_type_signature(sig):
    """ Parse a type signature """
    import re
    sig = sig.strip()
    if not sig:
        return None
    if ' -> ' in sig:
        parts = sig.split(' -> ')
        args_part = parts[0].strip()
        return_part = parts[1].strip()

        if '(' in args_part and args_part.endswith(')'):
            args_str = args_part[args_part.find('(')+1:-1]
            args = [a.strip() for a in args_str.split(',')] if args_str else []
        else:
            args = [args_part] if args_part else []

        return {'args': args, 'return': return_part}
    return {'args': [], 'return': sig}

