    """
    if hasattr(field, 'type_') and field.type_ is not None:
        try:
            from typing import ForwardRef, get_type_hints
            if isinstance(field.type_, ForwardRef):
                field.type_ = field.type_._evaluate(globalns, localns)
            elif hasattr(field.type_, '__forward_args__'):
                # Handle generic types containing ForwardRefs
                # This is a simplified approach to trigger evaluation
