mgc_code:
def edit_distance(seq1, seq2, action_function=lowest_cost_action, test=operator.eq):
    """Computes the edit distance between the two given sequences.
    This uses the relatively fast method that only constructs
    two columns of the 2d array for edits.  This function actually uses four columns
    because we track the number of matches too.
    """
    if len(seq1) < len(seq2):
        seq1, seq2 = seq2, seq1

    if not seq2:
        return len(seq1)

    previous_column = range(len(seq2) + 1)
    for i, char1 in enumerate(seq1):
        current_column = [i + 1]
        for j, char2 in enumerate(seq2):
            insertions = previous_column[j + 1] + 1
            deletions = current_column[j] + 1
            substitutions = previous_column[j] + (0 if test(char1, char2) else 1)
            current_column.append(min(insertions, deletions, substitutions))
        previous_column = current_column

    return previous_column[-1]

