def learningCurve(expPath, suite):
  """
  Print the test and overall noise errors from each iteration of this experiment
  """
  import json
  import os

  data = {}
  for filename in os.listdir(expPath):
      if filename.endswith('.json'):
          with open(os.path.join(expPath, filename), 'r') as f:
              data[filename] = json.load(f)

  iterations = sorted(data.keys())
  print(f"{'Iteration':<15} {'Overall Noise':<20}")
  for it in iterations:
      overall = data[it].get('overall_noise', 'N/A')
      print(f"{it:<15} {overall:<20}")

      print(f"  Tests for {it}:")
      tests = data[it].get('tests', {})
      for test_name in suite:
          if test_name in tests:
              noise = tests[test_name].get('noise', 'N/A')
              print(f"    {test_name:<20} {noise}")
      print("-" * 40)

