def convert_rom(ADDR_WIDTH=8, DATA_WIDTH=8, CONTENT=(4,5,6,7)):
    """ Convert ROM"""
    rom_dict = {}
    for i, value in enumerate(CONTENT):
        addr = format(i, f'0{ADDR_WIDTH}b')
        data = format(value, f'0{DATA_WIDTH}b')
        rom_dict[addr] = data
    return rom_dict

