def on_button_release(self, event):
        """Select or deselect rubber banded groups of items

         The selection of elements is prior and never items are selected or deselected at the same time.
         """
        if not hasattr(self, 'rubber_band'):
            return

        selection_box = self.rubber_band.get_bounds()
        items_in_box = self.get_items_in_area(selection_box)

        if event.key == 'Control':
            for item in items_in_box:
                item.set_selected(not item.is_selected())
        else:
            self.clear_selection()
            for item in items_in_box:
                item.set_selected(True)

        self.rubber_band.hide()
        self.update_canvas()

