import requests
from concurrent.futures import ThreadPoolExecutor
from typing import Optional, List

base_url = "https://geobc.gov.bc.ca/data/rest/services/geobc/bc_dataset_wfs/WFSService"
params = {
    "service": "WFS",
    "version": "2.0.0",
    "request": "GetFeature",
    "typeName": dataset,
    "outputFormat": "application/json",
    "count": pagesize,
}

if query:
    params["cql_filter"] = query
if bounds:
    params["bbox"] = f"{bounds[0]},{bounds[1]},{bounds[2]},{bounds[3]}"
if crs:
    params["srsName"] = crs
if sortby:
    params["sortBy"] = sortby

def fetch_page(start_index):
    page_params = params.copy()
    page_params["startIndex"] = start_index
    response = requests.get(base_url, params=page_params)
    response.raise_for_status()
    return response.json()

all_features = []
start_index = 0

while True:
    futures = []
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for i in range(0, pagesize * max_workers, pagesize):
            futures.append(executor.submit(fetch_page, start_index + i))

    batch_results = [f.result() for f in futures]

    for result in batch_results:
        features = result.get("features", [])
        all_features.extend(features)
        if not features:
            return {"type": "FeatureCollection", "features": all_features}

    if len(batch_results[-1].get("features", [])) < pagesize:
        break

    start_index += pagesize * max_workers

return {"type": "FeatureCollection", "features": all_features}

