mgc_code:
def save_workflow_to_cache(self, serialized_wf_instance):
        """
        If we aren't come to the end of the wf,
        saves the wf state and task_data to cache

        Task_data items that starts with underscore "_" are treated as
         local and does not passed to subsequent task steps.
        """
        if not serialized_wf_instance.is_completed():
            filtered_task_data = {
                k: v for k, v in serialized_wf_instance.task_data.items()
                if not k.startswith('_')
            }
            cache_payload = {
                'state': serialized_wf_instance.state,
                'task_data': filtered_task_data
            }
            self.cache.set(serialized_wf_instance.workflow_id, cache_payload)

