def load_formatter_fn(formatter):
    """
    >>> load_formatter_fn('logagg.formatters.basescript') #doctest: +ELLIPSIS
    <function basescript at 0x...>
    """
    import importlib

    try:
        module_path, func_name = formatter.rsplit('.', 1)
        module = importlib.import_module(module_path)
        return getattr(module, func_name)
    except (ValueError, ImportError, AttributeError):
        raise ImportError(f"Could not load formatter function: {formatter}")

