    if include_missing:
        # Ensure NaN is included in the categories/levels
        lvl = dim.levels if hasattr(dim, 'levels') else dim.unique()
        if not any(np.isnan(x) if isinstance(x, float) else False for x in lvl):
            lvl = np.append(lvl, np.nan)
        levels.append(lvl)
    else:
