    try:
        # Map the actual coordinate values to their integer indices in 'levels'
        idx = tuple(
            np.where(levels[i] == coord[i])[0][0]
            for i in range(len(dims))
        )
        result[idx] = value if weighted else 1
    except (IndexError, ValueError):
        continue

if prune:
    # Remove slices that are all zeros
    while result.ndim > 0:
        all_zero = np.all(result == 0, axis=tuple(range(result.ndim - 1)))
        if not np.any(all_zero):
            break
        # This is a simplified pruning logic
