def import_units(module, namespace):
    """Import Unit objects from a module into a namespace"""
    import inspect
    from types import ModuleType

    if not isinstance(module, ModuleType):
        raise TypeError("module must be a module object")

    for name, obj in inspect.getmembers(module):
        if hasattr(obj, '__class__') and obj.__class__.__name__ == 'Unit':
            setattr(namespace, name, obj)

