def _to_service(self, thing):
        """Convert to Analysis Service

        :param thing: UID/Catalog Brain/Object/Something
        :returns: Analysis Service object or None
        """
        if thing is None:
            return None
        try:
            from brain import AnalysisService
            if hasattr(thing, 'uid'):
                uid = thing.uid
            elif isinstance(thing, str):
                uid = thing
            else:
                return None
            return AnalysisService(uid)
        except (ImportError, Exception):
