mgc_code:
def _match_data_sets(x,y):
    """
    Makes sure everything is the same shape. "Intelligently".
    """
    import numpy as np

    x = np.asanyarray(x)
    y = np.asanyarray(y)

    if x.shape == y.shape:
        return x, y

    if x.ndim != y.ndim:
        if x.ndim == 0:
            x = np.full(y.shape, x)
        elif y.ndim == 0:
            y = np.full(x.shape, y)
        elif x.ndim == 1 and y.ndim > 1:
            x = np.broadcast_to(x, y.shape)
        elif y.ndim == 1 and x.ndim > 1:
            y = np.broadcast_to(y, x.shape)
        else:
            try:
                return np.broadcast_arrays(x, y)
            except ValueError:
                raise ValueError(f"Cannot match shapes {x.shape} and {y.shape}")

    return x, y

