def _parse_caps_bank(bank):
    """
    Parse the <bank> element of the connection capabilities XML.
    """
    capabilities = {}
    for cap in bank.findall('capability'):
        name = cap.get('name')
        value = cap.get('value')
        if name:
            capabilities[name] = value
    return capabilities

