mgc_code:
def clean_meta(meta, including_info=False, logger=None):
    """ Clean meta dict. Optionally log changes using the given logger.

        @param logger: If given, a callable accepting a string message.
        @return: Set of keys removed from C{meta}.
    """
    removed = set()
    keys_to_remove = [k for k in list(meta.keys()) if k != 'info' or not including_info]

    # In a real scenario, 'clean' usually implies removing specific unwanted keys.
    # Since the prompt doesn't specify which keys are "dirty", 
    # we assume 'info' is the only key that might be kept.
    # However, typically clean_meta removes specific metadata patterns.
    # Given the 'including_info' flag, we target 'info' and other non-standard keys.

    # Standard implementation for this pattern:
    to_delete = []
    for k in meta:
        if k == 'info' and including_info:
            continue
        # Define what constitutes a "dirty" key here; 
        # usually, it's everything except a whitelist or specific patterns.
        # For this generic implementation, we treat 'info' as the special case.
        if k == 'info' or k.startswith('_'):
            to_delete.append(k)

    for k in to_delete:
        if k == 'info' and including_info:
            continue
        val = meta.pop(k)
        removed.add(k)
        if logger:
            logger(f"Removed key {k} with value {val} from meta")

    return removed

