def raw_content(self, output=None, str_output=None):
        """Searches for `output` regex match within content of page, regardless of mimetype."""
        import re
        content = self.content if hasattr(self, 'content') else b''
        if isinstance(content, bytes):
            try:
                content = content.decode('utf-8')
            except UnicodeDecodeError:
                content = content.decode('latin-1')

        if str_output is not None:
            return content if str_output else None

        if output is None:
            return content

        match = re.search(output, content)
        return match.group(0) if match else None

