def dump_bulk(cls, parent=None, keep_ids=True):
        """Dumps a tree branch to a python data structure."""
        data = {}
        for child in cls.children:
            child_id = child.id if keep_ids else None
            key = child_id if child_id is not None else child.name
            data[key] = child.dump_bulk(parent=cls, keep_ids=keep_ids)
        return data

