import numpy as np
from scipy.signal import find_peaks

if method == 'above_thresh':
    mask = dat > value
    events = []
    i = 0
    while i < len(mask):
        if mask[i]:
            start = i
            while i < len(mask) and mask[i]:
                i += 1
            end = i - 1
            peak = np.argmax(dat[start:end+1]) + start
            events.append([start, peak, end])
        else:
            i += 1
    return np.array(events, dtype='int')

elif method == 'below_thresh':
    mask = dat < value
    events = []
    i = 0
    while i < len(mask):
        if mask[i]:
            start = i
            while i < len(mask) and mask[i]:
                i += 1
            end = i - 1
            peak = np.argmin(dat[start:end+1]) + start
            events.append([start, peak, end])
        else:
            i += 1
    return np.array(events, dtype='int')

elif method == 'maxima':
    peaks, _ = find_peaks(dat, distance=value)
    events = []
    for p in peaks:
        # Find start: first local min to the left
        start = p
        while start > 0 and dat[start-1] > dat[start]:
            start -= 1
        # Find end: first local min to the right
        end = p
        while end < len(dat) - 1 and dat[end+1] > dat[end]:
            end += 1
        events.append([start, p, end])
    return np.array(events, dtype='int')

else:
    raise ValueError("Method must be 'above_thresh', 'below_thresh' or 'maxima'")

