def get(cls, **kwargs):
        """
        Generic get() for one item only

        >>> ec2.instances.get(name='production-web-01')
        <Instance: ...>
        """
        for key, value in kwargs.items():
            for item in cls:
                if getattr(item, key, None) == value:
                    return item
        return None

