def aggregate(self, dimensions=None, function=None, spreadfn=None, **kwargs):
        """Applies a aggregate function to all ViewableElements.

        See :py:meth:`Dimensioned.opts` and :py:meth:`Apply.__call__`
        for more information.
        """
        if dimensions is None:
            dimensions = self.dimensions
        if function is None:
            function = self.default_aggregate_function
        if spreadfn is None:
            spreadfn = self.default_spread_function

        return self.apply(function, dimensions=dimensions, spreadfn=spreadfn, **kwargs)

