def create_driver(self):
        """Create a selenium driver using specified config properties

        :returns: a new selenium driver
        :rtype: selenium.webdriver.remote.webdriver.WebDriver
        """
        from selenium import webdriver
        from selenium.webdriver.chrome.service import Service as ChromeService
        from selenium.webdriver.firefox.service import Service as FirefoxService
        from webdriver_manager.chrome import ChromeDriverManager
        from webdriver_manager.firefox import GeckoDriverManager

        browser = self.config.get('browser', 'chrome').lower()
        options = webdriver.ChromeOptions() if browser == 'chrome' else webdriver.FirefoxOptions()

        if hasattr(self.config, 'get_options'):
            for key, value in self.config.get_options().items():
                options.add_argument(key if isinstance(key, str) else f"--{key}")

        if browser == 'chrome':
            return webdriver.Chrome(service=ChromeService(ChromeDriverManager().install()), options=options)
        elif browser == 'firefox':
            return webdriver.Firefox(service=FirefoxService(GeckoDriverManager().install()), options=options)
        else:
            raise ValueError(f"Unsupported browser: {browser}")

