                   groups=None,
                   publish_validate=False,
                   minions=None,
                   whitelist=None):
        """
        Returns a bool which defines if the requested function is authorized.
        Used to evaluate the standard structure under external master
        authentication interfaces, like eauth, peer, peer_run, etc.
        """
        if whitelist and tgt in whitelist:
            return True

        if groups is None:
            groups = []

        for auth in auth_list:
            if auth.get('type') == 'peer':
                if auth.get('peer') == tgt:
                    if not funs or any(f in auth.get('funs', []) for f in funs):
                        return True
            elif auth.get('type') == 'group':
                if any(g in auth.get('groups', []) for g in groups):
                    if not funs or any(f in auth.get('funs', []) for f in funs):
                        return True

        if minions and tgt in minions:
            return True

        if publish_validate:
            return False

        return False

