def join_impl(other, join_type, sequence):
    """
    Implementation for join_t
    :param other: other sequence to join with
    :param join_type: join type (inner, outer, left, right)
    :param sequence: first sequence to join with
    :return: joined sequence
    """
    if join_type == "inner":
        return inner_join_impl(other, sequence)
    seq_dict = {}
    for element in sequence:
        seq_dict[element[0]] = element[1]
    seq_kv = seq_dict
    other_kv = dict(other)
    if join_type == "left":
        keys = seq_kv.keys()
    elif join_type == "right":
        keys = other_kv.keys()
    elif join_type == "outer":
        keys = set(list(seq_kv.keys()) + list(other_kv.keys()))
    else:
        raise TypeError("Wrong type of join specified")
    result = {}
    for k in keys:
        result[k] = (seq_kv.get(k), other_kv.get(k))
    return six.viewitems(result)

mgc_code:
def join_impl(other, join_type, sequence):
    """
    Implementation for join_t
    :param other: other sequence to join with
    :param join_type: join type (inner, outer, left, right)
    :param sequence: first sequence to join with
    :return: joined sequence
    """
    from collections import defaultdict

    left_map = defaultdict(list)
    for i, item in enumerate(sequence):
        left_map[item].append(i)

    right_map = defaultdict(list)
    for j, item in enumerate(other):
        right_map[item].append(j)

    all_keys = set(left_map.keys()) | set(right_map.keys())
    result = []

    for key in all_keys:
        l_indices = left_map.get(key, [])
        r_indices = right_map.get(key, [])

        if not l_indices and not r_indices:
            continue

        if not l_indices:
            if join_type in ('outer', 'right'):
                for r_idx in r_indices:
                    result.append((None, other[r_idx]))
            continue

        if not r_indices:
            if join_type in ('outer', 'left'):
                for l_idx in l_indices:
                    result.append((sequence[l_idx], None))
            continue

        for l_idx in l_indices:
            for r_idx in r_indices:
                result.append((sequence[l_idx], other[r_idx]))

    return result

