mgc_code:
def get_sync_acl_cmds(self, switch_acls, expected_acls):
        """Returns the list of commands required synchronize switch ACLs

        1. Identify unexpected ACLs and delete them
        2. Iterate over expected ACLs
           a. Add missing ACLs + all rules
           b. Delete unexpected rules
           c. Add missing rules
        """
        cmds = []

        # 1. Identify unexpected ACLs and delete them
        for acl_name in list(switch_acls.keys()):
            if acl_name not in expected_acls:
                cmds.append(f"no ip access-list extended {acl_name}")

        # 2. Iterate over expected ACLs
        for acl_name, expected_rules in expected_acls.items():
            if acl_name not in switch_acls:
                # 2a. Add missing ACLs + all rules
                cmds.append(f"ip access-list extended {acl_name}")
                for rule in expected_rules:
                    cmds.append(f" {rule}")
            else:
                switch_rules = switch_acls[acl_name]
                # 2b. Delete unexpected rules
                for rule in switch_rules:
                    if rule not in expected_rules:
                        cmds.append(f"ip access-list extended {acl_name}")
                        cmds.append(f" no {rule}")

                # 2c. Add missing rules
                for rule in expected_rules:
                    if rule not in switch_rules:
                        cmds.append(f"ip access-list extended {acl_name}")
                        cmds.append(f" {rule}")

        return cmds

