def get_fn_plan(callback=None, out_callback=None, name='pycbc_cufft', parameters=None):
    """ Get the IFFT execute and plan functions
    """
    if parameters is None:
        parameters = {}

    import pycbc_cufft

    plan_fn = pycbc_cufft.plan_ifft
    exec_fn = pycbc_cufft.execute_ifft

    def wrapped_plan(*args, **kwargs):
        plan = plan_fn(*args, **kwargs)
        if callback:
            callback(plan)
        return plan

    def wrapped_exec(*args, **kwargs):
        result = exec_fn(*args, **kwargs)
        if out_callback:
            out_callback(result)
        return result

    return wrapped_exec, wrapped_plan

