def parse(text):
        """Try to parse into a date.

        Return:
            tuple (year, month, date) if successful; otherwise None.
        """
        import datetime
        for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y", "%Y/%m/%d", "%B %d, %Y", "%d %B %Y"):
            try:
                dt = datetime.datetime.strptime(text, fmt)
                return (dt.year, dt.month, dt.day)
            except ValueError:
                continue
        return None

