from celery.app.control import Inspect
from django.db import transaction
from myapp.models import Job  # Assuming Job model exists in myapp

app = Inspect()
active_tasks = app.active() or {}
reserved_tasks = app.reserved() or {}

# Flatten all active/reserved task IDs into a set
all_celery_ids = set()
for worker in active_tasks.values():
    for task in worker:
        all_celery_ids.add(task['id'])
for worker in reserved_tasks.values():
    for task in worker:
        all_celery_ids.add(task['id'])

with transaction.atomic():
    # Find jobs marked as 'running' (or similar) that aren't in Celery's current state
    dead_jobs = Job.objects.filter(status='RUNNING').exclude(id__in=all_celery_ids)
    dead_jobs.update(status='FAILED', error='Job lost due to server crash or limbo')

