mgc_code:
def dms2dec(dms):
    """
    Convert latitude from degrees,minutes,seconds in string or 3-array
   format to decimal degrees.
    """
    if isinstance(dms, str):
        import re
        parts = re.findall(r"[-+]?\d*\.\d+|\d+", dms)
        d, m, s = map(float, parts[:3])
    else:
        d, m, s = map(float, dms)

    sign = -1 if d < 0 or (d == 0 and any(x < 0 for x in dms if isinstance(dms, (list, tuple)))) else 1
    if isinstance(dms, str) and '-' in dms:
        sign = -1 if dms.strip().startswith('-') else 1

    abs_d = abs(d)
    return sign * (abs_d + m/60.0 + s/3600.0)

