from contextlib import contextmanager

@contextmanager
def option(current_kwargs, **kwargs):
    """
    Context manager for temporarily setting a keyword argument and
    then restoring it to whatever it was before.
    """
    original_values = {k: current_kwargs.get(k) for k in kwargs}
    current_kwargs.update(kwargs)
    try:
        yield
    finally:
        for k, v in original_values.items():
            if v is None and k not in current_kwargs:
                current_kwargs.pop(k, None)
            else:
                current_kwargs[k] = v

