def equal (a, b):
    """ Returns True iff 'a' contains the same elements as 'b', irrespective of their order.
        # TODO: Python 2.4 has a proper set class.
    """
    if len(a) != len(b):
        return False
    try:
        return set(a) == set(b)
    except TypeError:
        import collections
        return collections.Counter(a) == collections.Counter(b)

