def validate_user_threaded_json(pjson):
        """Takes a parsed JSON dict representing a set of tests in the user-threaded 
        format and validates it."""
        if not isinstance(pjson, dict):
            raise ValueError("JSON must be a dictionary")

        if "tests" not in pjson or not isinstance(pjson["tests"], list):
            raise ValueError("JSON must contain a 'tests' list")

        for i, test in enumerate(pjson["tests"]):
            if not isinstance(test, dict):
                raise ValueError(f"Test at index {i} must be a dictionary")

            required_fields = ["name", "threads"]
            for field in required_fields:
                if field not in test:
                    raise ValueError(f"Test at index {i} is missing required field: {field}")

            if not isinstance(test["threads"], list):
                raise ValueError(f"Threads in test {i} must be a list")

            for j, thread in enumerate(test["threads"]):
                if not isinstance(thread, list):
                    raise ValueError(f"Thread {j} in test {i} must be a list of steps")

                for k, step in enumerate(thread):
                    if not isinstance(step, dict):
                        raise ValueError(f"Step {k} in thread {j} of test {i} must be a dictionary")
                    if "action" not in step:
                        raise ValueError(f"Step {k} in thread {j} of test {i} must have an 'action'")
