mgc_code:
def _intersected_edge(self, edges, cut_edge):
        """ Given a list of *edges*, return the first that is intersected by
        *cut_edge*.
        """
        for edge in edges:
            if edge == cut_edge:
                continue
            # Check for intersection between two line segments (edge and cut_edge)
            # Assuming edges are tuples of points ((x1, y1), (x2, y2))
            p1, p2 = edge
            p3, p4 = cut_edge

            def ccw(A, B, C):
                return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])

            if ccw(p1, p3, p4) != ccw(p2, p3, p4) and ccw(p1, p2, p3) != ccw(p1, p2, p4):
                return edge
        return None

