def find_sphinx_build_dir():
    """
    Find build subfolder within sphinx docs directory.

    This is called by :func:`commit_docs` if keyword arg ``built_docs`` is not
    specified on the command line.
    """
    import os
    docs_dir = os.environ.get('SPHINX_DOCS_DIR', 'docs')
    for folder in os.listdir(docs_dir):
        path = os.path.join(docs_dir, folder)
        if os.path.isdir(path) and (folder == 'build' or folder.startswith('_build')):
            return path
    return os.path.join(docs_dir, 'build')

