nan = float("nan")

def sformat(segment, stat):
    FMT = "n={0}, mean={1}, p50/95={2}/{3}, max={4}"
    line_segs = [segment]
    for s in [stat]:
        p = s.get_percentiles()
        p50, p95 = p.get(0.50, nan), p.get(0.95, nan)
        line_segs.append(FMT.format(s.n, s.mean, p50, p95, s.max))
    return '{0}: {1}'.format(*line_segs)

