def pformat(self, prefix=()):
        """
        Makes a pretty ASCII format of the data, suitable for
        displaying in a console or saving to a text file.
        Returns a list of lines.
        """
        lines = []
        indent = "  " * len(prefix)

        def _recurse(data, current_prefix):
            curr_indent = "  " * len(current_prefix)
            if isinstance(data, dict):
                if not data:
                    lines.append(f"{curr_indent}{{}}")
                else:
                    lines.append(f"{curr_indent}{{")
                    for k, v in data.items():
                        lines.append(f"{curr_indent}  {repr(k)}: ")
                        _recurse(v, current_prefix + (k,))
                    lines.append(f"{curr_indent}}}")
            elif isinstance(data, (list, tuple, set)):
                if not data:
                    lines.append(f"{curr_indent}{repr(type(data)())}")
                else:
                    opening, closing = {list: ("[", "]"), tuple: ("(", ")"), set: ("{", "}")}[type(data)]
                    lines.append(f"{curr_indent}{opening}")
                    for i, v in enumerate(data):
                        lines.append(f"{curr_indent}  {i}: ")
                        _recurse(v, current_prefix + (i,))
                    lines.append(f"{curr_indent}{closing}")
            else:
                lines.append(f"{curr_indent}{repr(data)}")

        _recurse(self.data if hasattr(self, 'data') else self, prefix)
        return lines

