mgc_code:
def get_gradient(self, value, colors, upper_limit=100):
        """
        Map a value to a color
        :param value: Some value
        :return: A Hex color code
        """
        normalized = max(0, min(1, value / upper_limit))
        idx = normalized * (len(colors) - 1)
        low = int(idx)
        high = min(low + 1, len(colors) - 1)
        frac = idx - low

        def hex_to_rgb(hex_code):
            hex_code = hex_code.lstrip('#')
            return tuple(int(hex_code[i:i+2], 16) for i in (0, 2, 4))

        def rgb_to_hex(rgb):
            return '#{:02x}{:02x}{:02x}'.format(*map(int, rgb))

        c1 = hex_to_rgb(colors[low])
        c2 = hex_to_rgb(colors[high])

        interp = tuple(c1[i] + (c2[i] - c1[i]) * frac for i in range(3))
        return rgb_to_hex(interp)

