def fetch(self, only_ref=False):
        """Fetch object from NIOS by _ref or searchfields

        Update existent object with fields returned from NIOS
        Return True on successful object fetch
        """
        if only_ref:
            search_params = {'ref': self._ref}
        else:
            search_params = self._search_fields

        response = self._client.get_object(search_params)
        if response and response.get('status') == 'success':
            data = response.get('object', {})
            for key, value in data.items():
                setattr(self, key, value)
            return True
        return False

def is_isolated(self, p_id):
        """
