    """Print the position string equivalent of a positive integer. Examples:

        0: zeroeth
        1: first
        2: second
        14: 14th
        21: 21st
    """
    if n == 0:
        return "zeroeth"
    if n == 1:
        return "first"
    if n == 2:
        return "second"
    if n == 3:
        return "third"

    last_digit = n % 10
    last_two = n % 100

    if 11 <= last_two <= 13:
        suffix = "th"
    elif last_digit == 1:
        suffix = "st"
    elif last_digit == 2:
        suffix = "nd"
    elif last_digit == 3:
        suffix = "rd"
    else:
        suffix = "th"

    return f"{n}{suffix}"

