import inspect
from typing import Type, Any, Dict, get_type_hints

signature = inspect.signature(cls.__init__)
kwargs = {}
type_hints = get_type_hints(cls.__init__)

for name, param in signature.parameters.items():
    if name == 'self':
        continue

    if name in extras:
        kwargs[name] = extras[name]
        continue

    if name in params:
        val = params[name]
        # If the value is already the correct type, use it
        # Otherwise, check if the type has a from_params method
        param_type = type_hints.get(name)
        if param_type and not isinstance(val, param_type):
            if hasattr(param_type, 'from_params'):
                kwargs[name] = param_type.from_params(val)
            else:
                kwargs[name] = val
        else:
            kwargs[name] = val
    elif param.default is not inspect.Parameter.empty:
        kwargs[name] = param.default

kwargs.update(extras)
return kwargs

