mgc_code:
def _validate(self, validator, data, key, position=None, includes=None):
        """
        Run through a schema and a data structure,
        validating along the way.

        Ignores fields that are in the data structure, but not in the schema.

        Returns an array of errors.
        """
        if validator is None:
            return errors

        if isinstance(validator, dict):
            if not isinstance(data, dict):
                errors.append(f"Expected dict at {key}")
                return errors
            for v_key, v_val in validator.items():
                current_key = f"{key}.{v_key}" if key else v_key
                current_pos = f"{position}[{v_key}]" if position else v_key
                if v_key in data:
                    errors.extend(self._validate(v_val, data[v_key], current_key, current_pos))
        elif isinstance(validator, list):
            if not isinstance(data, list):
                errors.append(f"Expected list at {key}")
                return errors
            for i, item in enumerate(data):
                current_key = f"{key}[{i}]"
                current_pos = f"{position}[{i}]" if position else f"[{i}]"
                errors.extend(self._validate(validator[0], item, current_key, current_pos))
        elif callable(validator):
            try:
                if not validator(data):
                    errors.append(f"Invalid value at {key}")
            except Exception as e:
                errors.append(f"Error validating {key}: {str(e)}")
        return errors

