def cleanup(logger, *args):
    """Environment's cleanup routine."""
    for arg in args:
        try:
            if hasattr(arg, 'close'):
                arg.close()
            elif hasattr(arg, 'stop'):
                arg.stop()
            elif hasattr(arg, 'cleanup'):
                arg.cleanup()
