mgc_code:
def format_result(line, line_num, txt):
    """ highlight the search result """
    import re
    search_term = txt
    if not search_term:
        return f"{line_num}: {line}"

    def highlight(match):
        return f"\033[1;31m{match.group(0)}\033[0m"

    highlighted_line = re.sub(re.escape(search_term), highlight, line, flags=re.IGNORECASE)
    return f"{line_num}: {highlighted_line}"

