def remove_group_roles(request, group, domain=None, project=None):
    """Removes all roles from a group on a domain or project."""
    if domain:
        roles = request.get_group_roles(group, domain=domain)
        for role in roles:
            request.remove_group_role(group, role, domain=domain)
    elif project:
        roles = request.get_group_roles(group, project=project)
        for role in roles:
            request.remove_group_role(group, role, project=project)

