mgc_code:
def graph_from_incidence_matrix(matrix, node_prefix='', directed=False):
    """Creates a basic graph out of an incidence matrix.

    The matrix has to be a list of rows of values
    representing an incidence matrix.
    The values can be anything: bool, int, float, as long
    as they can evaluate to True or False.
    """
    graph = {}
    num_nodes = len(matrix)
    if num_nodes == 0:
        return graph

    num_edges = len(matrix[0])
    nodes = [f"{node_prefix}{i}" for i in range(num_nodes)]
    for node in nodes:
        graph[node] = []

    for e in range(num_edges):
        connected_nodes = [nodes[n] for n in range(num_nodes) if matrix[n][e]]

        if not directed:
            if len(connected_nodes) == 2:
                u, v = connected_nodes
                graph[u].append(v)
                graph[v].append(u)
        else:
            # In a directed incidence matrix, typically -1 is source, 1 is target
            # If values are just truthy, we assume first truthy is source, second is target
            if len(connected_nodes) == 2:
                u, v = connected_nodes
                graph[u].append(v)

    return graph

