def noisy_wrap(__func: Callable) -> Callable:
    """Decorator to enable DebugPrint for a given function.

    Args:
        __func: Function to wrap
    Returns:
        Wrapped function

    """
    from functools import wraps

    @wraps(__func__)
    def wrapper(*args, **kwargs):
        if 'DebugPrint' in globals() or 'DebugPrint' in locals():
            DebugPrint(f"Calling {__func__.__name__} with args={args}, kwargs={kwargs}")
        return __func__(*args, **kwargs)
    return wrapper

