def decode_union(self, data_type, obj):
        """
        The data_type argument must be a Union.
        See json_compat_obj_decode() for argument descriptions.
        """
        import typing

        origin = typing.get_origin(data_type)
        if origin is not Union:
            raise TypeError(f"Expected Union type, got {data_type}")

        args = typing.get_args(data_type)
        for arg in args:
            try:
                # This assumes the existence of a general decode method
                # or a way to validate the type against the object.
                # In a typical json_compat implementation, we attempt
                # to decode using the specific type in the Union.
                return self.decode(arg, obj)
            except (ValueError, TypeError):
                continue

        raise TypeError(f"Object {obj} does not match any type in Union {data_type}")

