import re
results = []
capture = False
for line in ins:
    if marker in line:
        capture = True
        continue
    if capture:
        if not line.strip():
            continue
        try:
            # Assuming format_s is a regex or a pattern to match against
            # and we extract all numeric values from the line
            match = re.findall(r"[-+]?\d*\.\d+|\d+", line)
            if match:
                results.append(tuple(map(float, match)))
        except (ValueError, TypeError):
            pass
        # If the marker is a boundary, we might stop after one line or 
        # continue until a specific end condition. 
        # Standard /usr/bin/time output usually follows the marker immediately.
return results

