def collect(self):
        """Collect statistics from /proc/self/mountstats.

        Currently, we do fairly naive parsing and do not actually check
        the statvers value returned by mountstats.
        """
        stats = {}
        try:
            with open('/proc/self/mountstats', 'r') as f:
                content = f.read()
        except (IOError, OSError):
            return stats

        sections = content.split('\n\n')
        for section in sections:
            lines = section.strip().split('\n')
            if not lines:
                continue

            # First line contains the mount point and device
            header = lines[0].split()
            if len(header) < 3:
                continue
            mount_point = header[2]

            section_data = {}
            for line in lines[1:]:
                if not line or '=' not in line:
                    continue
                key, value = line.split('=', 1)
                section_data[key.strip()] = value.strip()

            stats[mount_point] = section_data
        return stats

