def parse_net_kwargs(kwargs):
    """Parse arguments for the estimator.

    Resolves dotted names and instantiated classes.

    Examples
    --------
    >>> kwargs = {'lr': 0.1, 'module__nonlin': 'torch.nn.Hardtanh(-2, max_val=3)'}
    >>> parse_net_kwargs(kwargs)
    {'lr': 0.1, 'module__nonlin': Hardtanh(min_val=-2, max_val=3)}

    """
    import importlib

    parsed = {}
    for key, value in kwargs.items():
        if isinstance(value, str) and '(' in value and value.endswith(')'):
            try:
                # Split the class path from the arguments
                class_path, args_str = value.split('(', 1)
                args_str = args_str[:-1]

                # Resolve the class/function
                module_path, class_name = class_path.rsplit('.', 1)
                module = importlib.import_module(module_path)
                cls = getattr(module, class_name)

                # Evaluate arguments safely
                # Note: eval is used here to match the behavior of resolving
                # instantiated classes from strings as implied by the docstring.
                args_dict = eval(f"dict( {args_str} )" if '=' in args_str else f"[{args_str}]") if args_str else []

                if isinstance(args_dict, dict):
                    parsed[key] = cls(**args_dict)
                else:
                    parsed[key] = cls(*args_dict)
            except Exception:
                parsed[key] = value
        else:
            parsed[key] = value
    return parsed

