mgc_code:
def next_up(x, context=None):
    """next_up(x): return the least representable float that's
    strictly greater than x.

    This operation is quiet:  flags are not affected.

    """
    import math
    if math.isnan(x):
        return x
    if x == float('inf'):
        return x
    if x == 0.0:
        return float('nextafter(0, 1)') if hasattr(math, 'nextafter') else 5e-324
    return math.nextafter(x, float('inf'))

