mgc_code:
def combine(self, other, name=None):
    """Combine with another PhaseGroup and return the result."""
    if name is None:
        name = self.name

    combined_phases = {}
    for phase, group in self.phases.items():
        combined_phases[phase] = group.copy()

    for phase, group in other.phases.items():
        if phase in combined_phases:
            combined_phases[phase].update(group)
        else:
            combined_phases[phase] = group.copy()

    return self.__class__(name, combined_phases)

