mgc_code:
def _GSE2_PAZ_read(gsefile):
    """
    Read the instrument response information from a GSE Poles and Zeros file.

    Formatted for files generated by the SEISAN program RESP.

    Format must be CAL2, not coded for any other format at the moment,
    contact the authors to add others in.

    :type gsefile: string
    :param gsefile: Path to GSE file

    :returns: Dictionary of poles, zeros, gain and sensitivity
    :rtype: dict
    """
    with open(gsefile, 'r') as f:
        lines = f.readlines()

    data = {}
    current_section = None

    for line in lines:
        line = line.strip()
        if not line or line.startswith('*'):
            continue

        if line.upper().startswith('CAL2'):
            current_section = 'CAL2'
            continue

        if current_section == 'CAL2':
            parts = line.split()
            if len(parts) >= 2:
                key = parts[0].strip(':')
                val = parts[1]
                if key == 'GAIN':
                    data['gain'] = float(val)
                elif key == 'SENS':
                    data['sensitivity'] = float(val)
                elif key == 'NP':
                    data['np'] = int(val)
                elif key == 'NZ':
                    data['nz'] = int(val)

    # Read poles and zeros
    poles = []
    zeros = []

    # Find where the numeric lists start (after the header keys)
    # In SEISAN RESP files, poles/zeros follow the NP/NZ definitions
    line_idx = 0
    while line_idx < len(lines):
        l = lines[line_idx].strip()
        if 'NP' in l or 'NZ' in l:
            # Skip to the lines containing the actual coefficients
            line_idx += 1
            # Read zeros first, then poles
            for _ in range(data.get('nz', 0)):
                while line_idx < len(lines) and not lines[line_idx].strip():
                    line_idx += 1
                if line_idx < len(lines):
                    zeros.append(complex(*map(float, lines[line_idx].split())))
                    line_idx += 1
            for _ in range(data.get('np', 0)):
                while line_idx < len(lines) and not lines[line_idx].strip():
                    line_idx += 1
                if line_idx < len(lines):
                    poles.append(complex(*map(float, lines[line_idx].split())))
                    line_idx

