def pub_ret(self, load, skip_verify=False):
        """
        Request the return data from a specific jid, only allowed
        if the requesting minion also initialted the execution.
        """
        if not skip_verify and any(key not in load for key in ('jid', 'id')):
            return {}
        else:
            auth_cache = os.path.join(
                    self.opts['cachedir'],
                    'publish_auth')
            if not os.path.isdir(auth_cache):
                os.makedirs(auth_cache)
            jid_fn = os.path.join(auth_cache, load['jid'])
            with salt.utils.files.fopen(jid_fn, 'r') as fp_:
                if not load['id'] == salt.utils.stringutils.to_unicode(fp_.read()):
                    return {}

            return self.local.get_cache_returns(load['jid'])

mgc_code:
def pub_ret(self, load, skip_verify=False):
        """
        Request the return data from a specific jid, only allowed
        if the requesting minion also initialted the execution.
        """
        if not self.is_initiator(load.get('jid')):
            return {'status': 'error', 'msg': 'Not the initiator of this execution'}

        data = self.get_return_data(load.get('jid'))
        if not data:
            return {'status': 'error', 'msg': 'No return data found for this jid'}

        if skip_verify:
            return {'status': 'ok', 'data': data}

        if not self.verify_signature(data):
            return {'status': 'error', 'msg': 'Signature verification failed'}

        return {'status': 'ok', 'data': data}

