    raise FileNotFoundError(f"File {bam} does not exist")

with pysam.AlignmentFile(bam, "rb") as samfile:
    if not samfile.is_sorted():
        raise ValueError("BAM file is not sorted by coordinate")

    if not samfile.has_index():
        pysam.index(bam)

    has_mapped = False
    for read in samfile:
