    """
    Convert a JSON response into a double iterable, by rows and columns
    Optionally add element type, and filter triples by language (on literals)
    """
    row_data = []
    for col in hdr:
        val = row.get(col)
        if val is None:
            row_data.append(None)
            continue

        if isinstance(val, dict) and 'value' in val:
            actual_val = val['value']
            vtype = val.get('type')
            lang_val = val.get('lang')

            if isinstance(actual_val, str) and lang:
