def CreateTaskStorage(self, task):
    """Creates a task storage.

    The task storage is used to store attributes created by the task.

    Args:
      task(Task): task.

    Returns:
      StorageWriter: storage writer.

    Raises:
      IOError: if the storage type is not supported.
      OSError: if the storage type is not supported.
    """
    storage_type = task.storage_type
    if storage_type == 'local':
        return LocalStorageWriter(task)
    elif storage_type == 'cloud':
        return CloudStorageWriter(task)
    elif storage_type == 'memory':
        return MemoryStorageWriter(task)
    else:
        raise IOError(f"Unsupported storage type: {storage_type}")

