mgc_code:
def find_cycle(self):
      """greedy search for a cycle"""
      visited = {}
      stack = []
      current = self.start_node if hasattr(self, 'start_node') else next(iter(self.nodes))

      while current is not None:
          if current in visited:
              return stack[visited[current]:]

          visited[current] = len(stack)
          stack.append(current)

          neighbors = self.get_neighbors(current) if hasattr(self, 'get_neighbors') else self.adj.get(current, [])
          current = neighbors[0] if neighbors else None

      return None

