def construct_mapping(self, node, deep=False):
        """
        Build the mapping for YAML
        """
        mapping = {}
        for key, value in node.items():
            if deep and isinstance(value, dict):
                mapping[key] = self.construct_mapping(value, deep=True)
            elif deep and isinstance(value, list):
                mapping[key] = [self.construct_mapping(item, deep=True) if isinstance(item, dict) else item for item in value]
