    return []

tails = []
tails_indices = []
prev = [None] * len(xs)

for i, x in enumerate(xs):
    low, high = 0, len(tails)
    while low < high:
        mid = (low + high) // 2
        if tails[mid] < x:
            low = mid + 1
        else:
            high = mid

    if low < len(tails):
        tails[low] = x
        tails_indices[low] = i
    else:
