import inspect
import ast

needed = set()

def find_fields(node):
    fields = set()
    for child in ast.walk(node):
        if isinstance(child, ast.Attribute):
            if isinstance(child.value, ast.Name) and child.value.id == 'self':
                fields.add(child.attr)
        elif isinstance(child, ast.Name):
            # This handles cases where fields might be accessed via local variables
            # but in the context of FieldArray, we primarily look for self.field
            pass
    return fields

def resolve_name(name):
    if name in arr.fields:
        needed.add(name)
        return

    attr = getattr(arr, name, None)
    if attr is None:
        return

    if hasattr(attr, '_fields'): # VirtualField or similar
        needed.update(attr._fields)
    elif inspect.isroutine(attr) or isinstance(attr, property):
        try:
            source = inspect.getsource(attr)
            tree = ast.parse(source)
            needed.update(find_fields(tree))
        except (TypeError, OSError):
            pass

if isinstance(names, str):
    names = [names]

for name in names:
    resolve_name(name)

return {f for f in needed if f in arr.fields}

