def literalize(self):
        """
        Return an expression where NOTs are only occurring as literals.
        Applied recursively to subexpressions.
        """
        if hasattr(self, 'args'):
            for i, arg in enumerate(self.args):
                self.args[i] = arg.literalize()

        if isinstance(self, Not) and hasattr(self.arg, 'literalize'):
            inner = self.arg.literalize()
            if isinstance(inner, Not):
                return inner.arg.literalize()

        return self

