def column_family_definition(keyspace, column_family):
    """
    Return a dictionary of column family definitions for the given
    keyspace/column_family

    CLI Example:

    .. code-block:: bash

        salt '*' cassandra.column_family_definition <keyspace> <column_family>

    """
    import subprocess
    import json

    cmd = ['cqlsh', '-e', f"DESCRIBE TABLE {keyspace}.{column_family};"]
    try:
        result = subprocess.check_output(cmd, stderr=subprocess.STDOUT, universal_newlines=True)
        return {"definition": result.strip()}
    except subprocess.CalledProcessError as e:
        return {"error": e.output.strip()}
    except Exception as e:
        return {"error": str(e)}

