def jsonp(func):
    """Wraps JSONified output for JSONP requests.
    http://flask.pocoo.org/snippets/79/
    """
    from flask import request, Response
    import json

    def wrapper(*args, **kwargs):
        response = func(*args, **kwargs)
        callback = request.args.get('callback')
        if callback:
            # Ensure the response is a string/bytes of JSON
            if hasattr(response, 'get_data'):
                data = response.get_data(as_text=True)
            else:
                data = json.dumps(response)

            # Wrap the JSON data in the callback function
            output = f"{callback}({data});"
            return Response(output, mimetype='application/javascript')
        return response
    return wrapper

def import_module(self, name):
        """Import a module into the bridge."""
        import importlib
        try:
            module = importlib.import_module(name)
            setattr(self, name, module)
            return module
        except ImportError as e:
            raise ImportError(f"Could not import module {name}: {e}")

