mgc_code:
def parse_url(url):
    """Parse Redis connection URI.

    Parse according to IANA specs:
    * https://www.iana.org/assignments/uri-schemes/prov/redis
    * https://www.iana.org/assignments/uri-schemes/prov/rediss

    Also more rules applied:

    * empty scheme is treated as unix socket path no further parsing is done.

    * 'unix://' scheme is treated as unix socket path and parsed.

    * Multiple query parameter values and blank values are considered error.

    * DB number specified as path and as query parameter is considered error.

    * Password specified in userinfo and as query parameter is
      considered error.
    """
    from urllib.parse import urlparse, parse_qs

    if not url:
        return None

    parsed = urlparse(url)
    scheme = parsed.scheme

    if not scheme:
        return {"path": url}

    if scheme not in ("redis", "rediss", "unix"):
        raise ValueError(f"Unsupported scheme: {scheme}")

    if scheme == "unix":
        path = parsed.netloc if parsed.netloc else parsed.path
        if not path:
            raise ValueError("Unix socket path is missing")
        return {"path": path}

    # Handle redis/rediss
    result = {
        "scheme": scheme,
        "host": parsed.hostname,
        "port": parsed.port,
        "password": parsed.password,
        "username": parsed.username,
    }

    # Parse query parameters
    query_params = parse_qs(parsed.query)
    for key, values in query_params.items():
        if len(values) > 1 or not values[0]:
            raise ValueError(f"Invalid query parameter: {key}")

    params = {k: v[0] for k, v in query_params.items()}

    # DB number logic
    db = None
    if parsed.path:
        path_parts = parsed.path.lstrip("/").split("/", 1)
        if path_parts[0]:
            try:
                db = int(path_parts[0])
            except ValueError:
                raise ValueError(f"Invalid DB number in path: {path_parts[0]}")

    if "db" in params:
        try:
            query_db = int(params["db"])
        except ValueError:
            raise ValueError(f"Invalid DB number in query: {params['db']}")
        if db is not None:
            raise ValueError("DB number specified both in path and query")
        db = query_db

    result["db"] = db

    # Password logic
    if "password" in params:
        if result["password"] is not None:
            raise ValueError("Password specified both in userinfo and query")
        result["password"] = params["password"]

    return result

