hwc_code:
def vtmlrender(vtmarkup, plain=None, strict=False, vtmlparser=VTMLParser()):
    """ Look for vt100 markup and render vt opcodes into a VTMLBuffer. """
    if isinstance(vtmarkup, VTMLBuffer):
        return vtmarkup.plain() if plain else vtmarkup
    try:
        vtmlparser.feed(vtmarkup)
        vtmlparser.close()
    except:
        if strict:
            raise
        buf = VTMLBuffer()
        buf.append_str(str(vtmarkup))
        return buf
    else:
        buf = vtmlparser.getvalue()
        return buf.plain() if plain else buf
    finally:
        vtmlparser.reset()

mgc_code:
def vtmlrender(vtmarkup, plain=None, strict=False, vtmlparser=VTMLParser()):
    """ Look for vt100 markup and render vt opcodes into a VTMLBuffer. """
    if plain is not None:
        return plain

    buffer = VTMLBuffer()
    parser = vtmlparser

    # Process the markup string through the parser
    # and write the resulting tokens/opcodes to the buffer
    for token in parser.parse(vtmarkup):
        if token.is_opcode:
            buffer.write_opcode(token.opcode, token.args)
        else:
            buffer.write_text(token.text)

    if strict and buffer.has_errors():
        raise ValueError("VTML rendering failed due to strict mode constraints")

    return buffer.render()

