def from_maildir(self, codes: str) -> FrozenSet[Flag]:
        """Return the set of IMAP flags that correspond to the letter codes.

        Args:
            codes: The letter codes to map.

        """
        mapping = {
            'S': Flag.SEEN,
            'D': Flag.DRAFT,
            'F': Flag.FLAGGED,
            'R': Flag.ANSWERED,
        }
        return frozenset(mapping[c] for c in codes if c in mapping)

