mgc_code:
def complete_tags(arg):
    """ Complete NIPAP prefix type
    """
    if not arg:
        return []
    prefixes = {
        'nipap:': ['type', 'id', 'name', 'description', 'version'],
    }
    for prefix, completions in prefixes.items():
        if arg.startswith(prefix):
            suffix = arg[len(prefix):]
            return [prefix + c for c in completions if c.startswith(suffix)]
    return []

