def autoRangeAll():
    pgImagePlot2d.setRange(axis=None, padding=0)

def autoRangeHorizontal():
    data = pgImagePlot2d.getSlicedArray()
    if data is not None and data.ndim > 0:
        y = pgImagePlot2d.getCrosshairPos()[1]
        idx = int(round(y))
        if 0 <= idx < data.shape[0]:
            line = data[idx, :]
            pgImagePlot2d.setRange(axis=None, padding=0) # Default behavior or custom logic
            # Note: In actual pgImagePlot2d context, this usually triggers a specific range update
