mgc_code:
def crossPlotAutoRangeMethods(pgImagePlot2d, crossPlot, intialItems=None):
    """ Creates an ordered dict with autorange methods for an PgImagePlot2d inspector.

        :param pgImagePlot2d: the range methods will work on (the sliced array) of this inspector.
        :param crossPlot: if None, the range will be calculated from the entire sliced array,
            if "horizontal" or "vertical" the range will be calculated from the data under the
            horizontal or vertical cross hairs
        :param intialItems: will be passed on to the  OrderedDict constructor.
    """
    from collections import OrderedDict

    def autoRangeAll():
        pgImagePlot2d.setRange(axis=None, padding=0)

    def autoRangeHorizontal():
        data = pgImagePlot2d.getSlicedArray()
        if data is not None and data.ndim > 0:
            y = pgImagePlot2d.getCrosshairPos()[1]
            idx = int(round(y))
            if 0 <= idx < data.shape[0]:
                line = data[idx, :]
                pgImagePlot2d.setRange(axis=None, padding=0) # Default behavior or custom logic
                # Note: In actual pgImagePlot2d context, this usually triggers a specific range update
                # based on the slice. For a generic implementation:
                pgImagePlot2d.setRange(axis=None, padding=0)

    def autoRangeVertical():
        data = pgImagePlot2d.getSlicedArray()
        if data is not None and data.ndim > 0:
            x = pgImagePlot2d.getCrosshairPos()[0]
            idx = int(round(x))
            if 0 <= idx < data.shape[1]:
                line = data[:, idx]
                pgImagePlot2d.setRange(axis=None, padding=0)

    methods = OrderedDict()
    if intialItems:
        methods.update(intialItems)

    if crossPlot is None:
        methods["Auto Range"] = autoRangeAll
    elif crossPlot == "horizontal":
        methods["Auto Range (Horizontal)"] = autoRangeHorizontal
    elif crossPlot == "vertical":
        methods["Auto Range (Vertical)"] = autoRangeVertical

    return methods

