def client_registration(self, context):
        """
        Handle the OIDC dynamic client registration.
        :type context: satosa.context.Context
        :rtype: oic.utils.http_util.Response

        :param context: the current context
        :return: HTTP response to the client
        """
        try:
            resp = self.provider.handle_client_registration_request(json.dumps(context.request))
            return Created(resp.to_json(), content="application/json")
        except InvalidClientRegistrationRequest as e:
            return BadRequest(e.to_json(), content="application/json")

mgc_code:
def client_registration(self, context):
        """
        Handle the OIDC dynamic client registration.
        :type context: satosa.context.Context
        :rtype: oic.utils.http_util.Response

        :param context: the current context
        :return: HTTP response to the client
        """
        registration_request = context.get_request().get_json()
        if not registration_request:
            return oic.utils.http_util.Response(status=400, body="Invalid JSON")

        client_id = self.generate_client_id()
        client_secret = self.generate_client_secret()

        registration_data = {
            "client_id": client_id,
            "client_secret": client_secret,
            "client_id_issued_at": int(time.time()),
        }

        for key in ["redirect_uris", "client_name", "grant_types", "response_types"]:
            if key in registration_request:
                registration_data[key] = registration_request[key]

        self.store_client(registration_data)

        return oic.utils.http_util.Response(
            status=201,
            body=json.dumps(registration_data),
            content_type="application/json"
        )

