def yaml_read_irred_perts(filename, doc_tag="!IrredPerts"):
    """Read the list of irreducible perturbations from file."""
    import yaml

    class IrredPertsLoader(yaml.SafeLoader):
        pass

    def irred_perts_constructor(loader, node):
        return loader.construct_sequence(node)

    IrredPertsLoader.add_constructor(doc_tag, irred_perts_constructor)
    with open(filename, 'r') as f:
        data = yaml.load(f, Loader=IrredPertsLoader)
    return data

