while True:
    try:
        user_input = await asyncio.to_thread(input, "cli> ")
        if not user_input:
            continue

        parts = user_input.split()
        cmd = parts[0]
        args = parts[1:]

        if cmd in ("exit", "quit"):
            break

        # Assuming the class has a method to handle commands
        if hasattr(self, f"do_{cmd}"):
            method = getattr(self, f"do_{cmd}")
            if asyncio.iscoroutinefunction(method):
                await method(*args)
            else:
                method(*args)
        else:
            print(f"Unknown command: {cmd}")
    except (EOFError, KeyboardInterrupt):
        break

