def read_glossaries(self):
        """
        Read all existing glossaries in the main aux-file.
        """
        self.glossaries = {}
        try:
            with open(self.aux_file, 'r', encoding='utf-8') as f:
                for line in f:
                    if line.startswith('glossary{'):
                        parts = line.strip().split('{', 2)
                        if len(parts) >= 3:
                            name = parts[1]
