mgc_code:
def process_remote_sources(raw_config, environment=None):
    """Stage remote package sources and merge in remote configs.

    Args:
        raw_config (str): the raw stacker configuration string.
        environment (dict, optional): any environment values that should be
            passed to the config

    Returns:
        str: the raw stacker configuration string

    """
    import yaml
    import requests
    import os

    config = yaml.safe_load(raw_config) or {}
    remote_sources = config.get('remote_sources', [])

    if not remote_sources:
        return raw_config

    merged_config = config.copy()

    for source in remote_sources:
        url = source.get('url')
        if not url:
            continue

        try:
            response = requests.get(url, timeout=10)
            response.raise_for_status()
            remote_data = yaml.safe_load(response.text)
            if isinstance(remote_data, dict):
                merged_config.update(remote_data)
        except (requests.RequestException, yaml.YAMLError):
            continue

    if environment:
        for key, value in environment.items():
            if key in merged_config and isinstance(merged_config[key], str):
                merged_config[key] = merged_config[key].format(**value)

    return yaml.dump(merged_config)

