def upload(self, local_fn, remote_fn=None, dont_overwrite=False):
    """Uploads file to remote instance. If location not specified, dumps it
    into default directory. Creates missing directories in path name."""
    if remote_fn is None:
        remote_fn = os.path.join(self.default_directory, os.path.basename(local_fn))

    remote_dir = os.path.dirname(remote_fn)
    if remote_dir:
        self.ssh.run(f'mkdir -p "{remote_dir}"')

    if dont_overwrite:
        check = self.ssh.run(f'test -f "{remote_fn}"', capture_output=True)
        if check.returncode == 0:
            return False

    self.sftp.put(local_fn, remote_fn)
    return True

