import weakref

if not jref.startswith('#'):
    raise ValueError("Only internal references starting with '#' are supported")

path = jref[1:]
if not path:
    return weakref.proxy(parser.root)

parts = path.split('/')
current = parser.root
for part in parts:
    if not part:
        continue
    if part.startswith('~0'):
        part = part.replace('~0', '~', 1)
    if part.startswith('~1'):
        part = part.replace('~1', '/', 1)

    try:
        if isinstance(current, list):
            current = current[int(part)]
        else:
            current = current[part]
    except (KeyError, IndexError, ValueError, TypeError):
        raise ValueError(f"Invalid path: {jref}")

return weakref.proxy(current)

