mgc_code:
def update_energy(self, bypass_check: bool = False):
        """Builds weekly, monthly and yearly dictionaries"""
        if not bypass_check:
            if not hasattr(self, 'energy_data') or not self.energy_data:
                return

        self.weekly_energy = {}
        self.monthly_energy = {}
        self.yearly_energy = {}

        for date_str, value in self.energy_data.items():
            from datetime import datetime
            dt = datetime.strptime(date_str, '%Y-%m-%d')

            year = dt.year
            month = dt.strftime('%Y-%m')
            week = dt.strftime('%Y-W%U')

            self.yearly_energy[year] = self.yearly_energy.get(year, 0) + value
            self.monthly_energy[month] = self.monthly_energy.get(month, 0) + value
            self.weekly_energy[week] = self.weekly_energy.get(week, 0) + value

