mgc_code:
def baltree(ntips, treeheight=1.0):
        """
        Returns a balanced tree topology.
        """
        if ntips <= 1:
            return ntips

        def build(n, h):
            if n == 1:
                return 0
            mid = n // 2
            left = build(mid, h / 2)
            right = build(n - mid, h / 2)
            return (left, right)

        return build(ntips, treeheight)

