mgc_code:
def strict_parse(cls, query_str, *specs, extra_parameters=True):
		""" Parse query and return :class:`.WStrictURIQuery` object

		:param query_str: query component of URI to parse
		:param specs: list of parameters specifications
		:param extra_parameters: whether parameters that was not specified in "specs" are allowed
		:return: WStrictURIQuery
		"""
		from urllib.parse import parse_qs

		parsed = parse_qs(query_str, keep_blank_values=True)
		spec_keys = {spec.name for spec in specs}

		if not extra_parameters:
		    for key in parsed:
		        if key not in spec_keys:
		            raise ValueError(f"Unexpected parameter: {key}")

		query_obj = cls()
		for spec in specs:
		    val = parsed.get(spec.name, [None])[0]
		    if val is None and spec.required:
		        raise ValueError(f"Missing required parameter: {spec.name}")
		    setattr(query_obj, spec.name, val)

		if extra_parameters:
		    for key, values in parsed.items():
		        if key not in spec_keys:
		            setattr(query_obj, key, values[0])

		return query_obj

