mgc_code:
def _read_zip(self, filepath):
        """
        Read an IPS installation zipfile and return the core version number
        @type   filepath:   str
        @rtype: LooseVersion
        """
        import zipfile
        from distutils.version import LooseVersion

        with zipfile.ZipFile(filepath, 'r') as z:
            for name in z.namelist():
                if name.endswith('version.txt'):
                    with z.open(name) as f:
                        return LooseVersion(f.read().decode('utf-8').strip())
            raise FileNotFoundError("Could not find version.txt in the zip archive")

