mgc_code:
def load_checkpoint(with_local=False):
    """Load latest check point.

    Parameters
    ----------
    with_local: bool, optional
        whether the checkpoint contains local model

    Returns
    -------
    tuple : tuple
        if with_local: return (version, gobal_model, local_model)
        else return (version, gobal_model)
        if returned version == 0, this means no model has been CheckPointed
        and global_model, local_model returned will be None
    """
    import os
    import torch

    checkpoint_path = 'checkpoint.pth'
    if not os.path.exists(checkpoint_path):
        return (0, None) if not with_local else (0, None, None)

    try:
        checkpoint = torch.load(checkpoint_path)
        version = checkpoint.get('version', 0)
        global_model = checkpoint.get('global_model', None)

        if with_local:
            local_model = checkpoint.get('local_model', None)
            return (version, global_model, local_model)
        return (version, global_model)
    except Exception:
        return (0, None) if not with_local else (0, None, None)

