def get_filename(page, content_type, data):
    """
    Generate a stable filename using the original filename of the type.


    """
    import re
    import hashlib

    filename = "unknown"
    if content_type and "application/octet-stream" not in content_type:
        if "filename=" in content_type:
            match = re.search(r'filename="?([^";\n\r]*)', content_type)
            if match:
                filename = match.group(1)

    if not filename or filename == "unknown":
        hash_val = hashlib.sha256(data).hexdigest()[:12]
        filename = f"file_{hash_val}"

    return f"page_{page}_{filename}"

