def check_argument_list(kernel_name, kernel_string, args):
    """ raise an exception if a kernel arguments do not match host arguments """
    import re

    pattern = r'\b' + re.escape(kernel_name) + r'\s*\([^)]*\)'
    match = re.search(pattern, kernel_string)
    if not match:
        raise Exception(f"Kernel {kernel_name} not found in kernel string")

    args_str = match.group(0)[match.group(0).find('(')+1:match.group(0).rfind(')')]
    if not args_str.strip():
        kernel_args = []
    else:
        kernel_args = [arg.strip() for arg in args_str.split(',')]

    if len(kernel_args) != len(args):
        raise Exception(f"Argument count mismatch for {kernel_name}: expected {len(kernel_args)}, got {len(args)}")

