def keys(self, latest=False):
        """
        Return a list of the keys in this directory.

        Parameters
        ----------

        latest : bool, optional (default=False)
            If True then return a list of keys with unique names where only the
            key with the highest cycle number is included where multiple keys
            exist with the same name.

        Returns
        -------

        keys : list
            List of keys

        """
        if latest:
            keys = {}
            for key in self.keys():
                name = key.GetName()
                if name in keys:
                    if key.GetCycle() > keys[name].GetCycle():
                        keys[name] = key
                else:
                    keys[name] = key
            return keys.values()
        return [asrootpy(key) for key in self.GetListOfKeys()]

def _explore_storage(self):
        """Generator of all files contained in media storage."""
        path = ''
        dirs = [path]
        while dirs:
            path = dirs.pop()
            subdirs, files = self.media_storage.listdir(path)
            for media_filename in files:
                yield os.path.join(path, media_filename)
            dirs.extend([os.path.join(path, subdir) for subdir in subdirs])

