mgc_code:
def __get_segments_from_node(node, graph):
    """Calculates the segments that can emanate from a particular node on the main cycle."""
    for neighbor in graph[node]:
        if neighbor not in graph:
            continue

        current = neighbor
        path = [node, neighbor]
        visited = {node, neighbor}

        while True:
            next_nodes = [n for n in graph[current] if n not in visited]
            if len(next_nodes) != 1:
                break
            current = next_nodes[0]
            path.append(current)
            visited.add(current)

        segments.append(path)
    return segments

