def check(text):
    """Advice on sudden vs suddenly."""
    import re
    pattern = r'\b(sudden)\b\s+(\w+ly)'
    if re.search(pattern, text, re.IGNORECASE):
        return "Consider using 'suddenly' instead of 'sudden' followed by an adverb."
    if re.search(r'\b(suddenly)\b\s+(\w+)', text, re.IGNORECASE):
        return "Check if 'sudden' (adjective) is more appropriate than 'suddenly' (adverb)."
    return "Correct usage."

