mgc_code:
def estimate_size_in_bytes(cls, magic, compression_type, key, value):
        """ Upper bound estimate of record size.
        """
        import sys

        # Base overhead for the record structure
        size = sys.getsizeof(magic) + sys.getsizeof(compression_type)

        # Estimate key size
        if isinstance(key, str):
            size += len(key) * 2 # Rough estimate for UTF-16/Unicode
        elif isinstance(key, bytes):
            size += len(key)
        else:
            size += sys.getsizeof(key)

        # Estimate value size
        if isinstance(value, (str, bytes, bytearray)):
            size += len(value)
        elif hasattr(value, '__len__'):
            size += sys.getsizeof(value) + (len(value) * 8) # Pointer overhead
        else:
            size += sys.getsizeof(value)

        return size

