mgc_code:
def get_all(self, cat):
        """
        if data can't found in cache then it will be fetched from db,
         parsed and stored to cache for each lang_code.

        :param cat: cat of catalog data
        :return:
        """
        cache_key = f"catalog_{cat}"
        cached_data = self.cache.get(cache_key)
        if cached_data:
            return cached_data

        db_data = self.db.fetch_catalog(cat)
        if not db_data:
            return None

        parsed_data = {}
        for item in db_data:
            lang_code = item.get('lang_code')
            if lang_code not in parsed_data:
                parsed_data[lang_code] = []
            parsed_data[lang_code].append(item)

        self.cache.set(cache_key, parsed_data)
        return parsed_data

