def gen_inherited(self) -> str:
        """ Generate the list of slot properties that are inherited across slot_usage or is_a paths """
        inherited_slots = set()
        queue = [self]
        visited = set()

        while queue:
            current = queue.pop(0)
            if current in visited:
                continue
            visited.add(current)

            if hasattr(current, 'slot_usage'):
                for usage in current.slot_usage:
                    inherited_slots.update(usage.slots)

            if hasattr(current, 'is_a') and current.is_a:
                queue.append(current.is_a)

        return ", ".join(sorted(inherited_slots))

