    # Assuming the subject is available in the context or as an argument
    # This implementation follows the logic: subject.identifiers IS NOT None
    from flask_security import current_user
    if current_user.identifiers is None:
        from flask_security import unauthorized
        return unauthorized()
    return fn(*args, **kwargs)
return wrapper

