mgc_code:
def requires_user(fn):
        """
        Requires that the calling Subject be *either* authenticated *or* remembered
        via RememberMe services before allowing access.

        This method essentially ensures that subject.identifiers IS NOT None
        """
        from functools import wraps

        @wraps(fn)
        def wrapper(*args, **kwargs):
            # Assuming the subject is available in the context or as an argument
            # This implementation follows the logic: subject.identifiers IS NOT None
            from flask_security import current_user
            if current_user.identifiers is None:
                from flask_security import unauthorized
                return unauthorized()
            return fn(*args, **kwargs)
        return wrapper

