def _get_conn(key=None,
              keyid=None,
              profile=None,
              region=None,
              **kwargs):
    """
    Create a boto3 client connection to EFS
    """
    client = None
    if profile:
        if isinstance(profile, six.string_types):
            if profile in __pillar__:
                profile = __pillar__[profile]
            elif profile in __opts__:
                profile = __opts__[profile]
    elif key or keyid or region:
        profile = {}
        if key:
            profile['key'] = key
        if keyid:
            profile['keyid'] = keyid
        if region:
            profile['region'] = region

    if isinstance(profile, dict):
        if 'region' in profile:
            profile['region_name'] = profile['region']
            profile.pop('region', None)
        if 'key' in profile:
            profile['aws_secret_access_key'] = profile['key']
            profile.pop('key', None)
        if 'keyid' in profile:
            profile['aws_access_key_id'] = profile['keyid']
            profile.pop('keyid', None)

        client = boto3.client('efs', **profile)
    else:
        client = boto3.client('efs')

    return client

mgc_code:
def _get_conn(key=None,
              keyid=None,
              profile=None,
              region=None,
              **kwargs):
    """
    Create a boto3 client connection to EFS
    """
    import boto3
    from botocore.config import Config

    session_kwargs = {}
    if profile:
        session_kwargs['profile_name'] = profile

    session = boto3.Session(**session_kwargs)

    client_kwargs = {'region_name': region}
    if key:
        client_kwargs['aws_access_key_id'] = key
    if keyid:
        client_kwargs['aws_secret_access_key'] = keyid

    client_kwargs.update(kwargs)

    return session.client('efs', **client_kwargs)

