mgc_code:
def update_record(self, identifier, rtype=None, name=None, content=None, **kwargs):
        """
        Update a record. Identifier must be specified.
        """
        if identifier is None:
            raise ValueError("Identifier must be specified")

        record = self.get_record(identifier)
        if record is None:
            raise KeyError(f"Record {identifier} not found")

        updates = {k: v for k, v in kwargs.items()}
        if rtype is not None:
            updates['rtype'] = rtype
        if name is not None:
            updates['name'] = name
        if content is not None:
            updates['content'] = content

        record.update(updates)
        self.save_record(record)
        return record

