mgc_code:
def blt(f: List[SYM], x: List[SYM]) -> Dict[str, Any]:
    """
    Sort equations by dependence
    """
    from collections import defaultdict, deque

    deps = defaultdict(set)
    nodes = set()

    for i, eq in enumerate(f):
        nodes.add(i)
        # Find all symbols in the equation that are targets of other equations
        # Assuming SYM objects can be iterated or checked for membership
        for j, other_eq in enumerate(f):
            if i == j: continue
            # If the target of equation j is present in equation i, i depends on j
            # This logic depends on the structure of SYM; assuming eq is a tuple/list
            # where the first element is the target.
            target_j = other_eq[0]
            if any(target_j == sym for sym in eq):
                deps[i].add(j)

    sorted_indices = []
    visited = set()
    temp_stack = set()

    def visit(n):
        if n in temp_stack:
            raise Exception("Cyclic dependency detected")
        if n not in visited:
            temp_stack.add(n)
            for m in deps[n]:
                visit(m)
            temp_stack.remove(n)
            visited.add(n)
            sorted_indices.append(n)

    for node in nodes:
        if node not in visited:
            visit(node)

    return {"sorted_equations": [f[i] for i in sorted_indices], "order": sorted_indices}

