def open(cls, title, conn=None, google_user=None,
             google_password=None):
        """ Open the spreadsheet named ``title``. If no spreadsheet with
        that name exists, a new one will be created. """
        if conn is None:
            raise ValueError("Connection 'conn' must be provided.")

        spreadsheets = conn.list_spreadsheets()
        for sheet in spreadsheets:
            if sheet['title'] == title:
                return cls(conn, sheet['id'])

        new_sheet = conn.create_spreadsheet(title)
        return cls(conn, new_sheet['id'])

