def load_bulk(cls, bulk_data, parent=None, keep_ids=False):
        """Loads a list/dictionary structure to the tree."""
        results = []
        for item in bulk_data:
            if isinstance(item, dict):
                obj = cls(**item)
            else:
                obj = cls(item)

            if parent:
                parent.add(obj)

            if not keep_ids:
                obj.id = None

            results.append(obj)
        return results

