mgc_code:
def compute_hash(attributes, ignored_attributes=None):
    """
    Computes a hash code for the given dictionary that is safe for persistence round trips 
    """
    if ignored_attributes is None:
        ignored_attributes = set()
    else:
        ignored_attributes = set(ignored_attributes)

    filtered_items = sorted(
        (k, v) for k, v in attributes.items() if k not in ignored_attributes
    )
    return hash(tuple(filtered_items))

