def load(self, image=None):
    """load an image, either an actual path on the filesystem or a uri.

       Parameters
       ==========
       image: the image path or uri to load (e.g., docker://ubuntu 

    """
    if image is None:
        raise ValueError("An image path or URI must be provided.")

