mgc_code:
def from_text(cls, text, mapping='mapping'):
        """
        Create a Profile instance from the Unicode graphemes found in `text`.

        Parameters
        ----------
        text
        mapping

        Returns
        -------
        A Profile instance.

        """
        import unicodedata

        graphemes = []
        current_grapheme = []

        for char in text:
            if unicodedata.combining(char):
                current_grapheme.append(char)
            else:
                if current_grapheme:
                    graphemes.append("".join(current_grapheme))
                    current_grapheme = []
                current_grapheme.append(char)
        if current_grapheme:
            graphemes.append("".join(current_grapheme))

        counts = {}
        for g in graphemes:
            counts[g] = counts.get(g, 0) + 1

        return cls(counts, mapping=mapping)

def computePointing(self, ra_deg, dec_deg, roll_deg, cartesian=False):
        """Compute a pointing model without changing the internal object pointing"""
        import numpy as np
        from astropy.coordinates import SkyCoord
        from astropy import units as u

        coord = SkyCoord(ra=ra_deg*u.deg, dec=dec_deg*u.deg, frame='icrs')

        if cartesian:
            return coord.cartesian.xyz.value

        return np.array([ra_deg, dec_deg, roll_deg])

