mgc_code:
def _getDevMajorMinor(self, devpath):
        """Return major and minor device number for block device path devpath.
        @param devpath: Full path for block device.
        @return:        Tuple (major, minor).

        """
        import os
        st = os.stat(devpath)
        rdev = st.st_rdev
        major = (rdev >> 20) & 0x3ff
        minor = rdev & 0xfffff
        return (major, minor)

