    new_jco = self.jco.get(row_names=obs_names, col_names=par_names)
else:
    new_jco = None
if astype is not None:
    new = astype(jco=new_jco, pst=new_pst, parcov=new_parcov,
                  obscov=new_obscov, predictions=new_preds,
                  verbose=False)
else:
