def run(self):
        """ Runs the printer loop in a subprocess. This is called by
            multiprocessing.
        """
        while True:
            try:
                job = self.queue.get()
                if job is None:
                    break
                self.printer.print_job(job)
            except Exception as e:
                self.logger.error(f"Printer loop error: {e}")

