if not headers:
    return

# HTTP header names are typically alphanumeric and certain symbols
# (hyphens), starting with a letter.
pattern = re.compile(r'^[A-Za-z][A-Za-z0-9\-]*$')

valid_headers = {}
for key, value in headers.items():
    if pattern.match(str(key)):
        valid_headers[key] = value

instance.request_headers = valid_headers

