mgc_code:
def event_sources(ctx, command):
    """List, enable, and disable event sources specified in the config file"""
    import click
    import yaml

    config_path = ctx.obj.get('config_path', 'config.yaml')
    with open(config_path, 'r') as f:
        config = yaml.safe_load(f) or {}

    sources = config.get('event_sources', {})

    if command == 'list':
        for name, settings in sources.items():
            status = 'enabled' if settings.get('enabled', True) else 'disabled'
            click.echo(f"{name}: {status}")
    elif command == 'enable':
        # Assuming a target source is provided via a context variable or argument
        target = ctx.params.get('source')
        if target in sources:
            sources[target]['enabled'] = True
            with open(config_path, 'w') as f:
                yaml.dump(config, f)
            click.echo(f"Enabled {target}")
        else:
            click.echo(f"Source {target} not found", err=True)
    elif command == 'disable':
        target = ctx.params.get('source')
        if target in sources:
            sources[target]['enabled'] = False
            with open(config_path, 'w') as f:
                yaml.dump(config, f)
            click.echo(f"Disabled {target}")
        else:
            click.echo(f"Source {target} not found", err=True)

