            return self.redis.zrangebyscore(key, '-inf', value, excl=True)
        elif filter_type == 'lte':
            return self.redis.zrangebyscore(key, '-inf', value)
        elif filter_type == 'between':
            return self.redis.zrangebyscore(key, value[0], value[1])
        else:
            raise ValueError(f"Unsupported filter type: {filter_type}")

