mgc_code:
def undefined_entries(self) -> Set[str]:
        """ Return the set of tokens that are referenced but not defined. """
        referenced = set()
        defined = set()
        for entry in self.entries:
            defined.add(entry.token)
            for ref in entry.references:
                referenced.add(ref)
        return referenced - defined

