mgc_code:
def user_cache_dir():
    r"""Return the per-user cache dir (full path).

    - Linux, *BSD, SunOS: ~/.cache/glances
    - macOS: ~/Library/Caches/glances
    - Windows: {%LOCALAPPDATA%,%APPDATA%}\glances\cache
    """
    import os
    import platform

    system = platform.system()
    home = os.path.expanduser("~")

    if system == "Windows":
        local_appdata = os.environ.get("LOCALAPPDATA")
        appdata = os.environ.get("APPDATA")
        base = local_appdata or appdata or os.path.join(home, "AppData", "Roaming")
        return os.path.join(base, "glances", "cache")
    elif system == "Darwin":
        return os.path.join(home, "Library", "Caches", "glances")
    else:
        return os.path.join(home, ".cache", "glances")

