async def getHiveKey(self, path):
        """ Get the value of a key in the cell default hive """
        import winreg
        import asyncio

        def _read_hive():
            try:
                # HKEY_CURRENT_USER is the default hive for cell/user settings
                with winreg.OpenKey(winreg.HKEY_CURRENT_USER, path, 0, winreg.KEY_READ) as key:
                    value, reg_type = winreg.QueryValueEx(key, None)
                    return value
            except FileNotFoundError:
                return None
            except Exception:
                return None

        return await asyncio.to_thread(_read_hive)

