import functools

@functools.wraps(wrapped)
def wrapper(*args, **kwargs):
    # If the wrapped function is a method, the first arg is usually the instance
    # If instance is explicitly provided, use it.
    target = instance if instance is not None else (args[0] if args else None)
    if target is None or not hasattr(target, '_gather'):
        raise TypeError("The wrapped function must be bound to an Ingredient instance.")
    yield from target._gather(*args, **kwargs)
return wrapper

