mgc_code:
def get_start_date(module, x):
    """ 曜日による最初の授業の日を返す """
    import datetime
    days = {"月": 0, "火": 1, "水": 2, "木": 3, "金": 4, "土": 5, "日": 6}
    target_day = days[x]
    today = datetime.date.today()
    days_ahead = target_day - today.weekday()
    if days_ahead < 0:
        days_ahead += 7
    return today + datetime.timedelta(days=days_ahead)

