    if state in nfa['initial_states']:
        if state in nfa['accepting_states']:
            g.node(str(state), root='true',
                   shape='doublecircle')
        else:
            g.node(str(state), root='true')
    elif state in nfa['accepting_states']:
        g.node(str(state), shape='doublecircle')
    else:
