def decode(cls, s):
        """decodes a base64 string to plain text

        :param s: unicode str|bytes, the base64 encoded string
        :returns: unicode str
        """
        import base64
        if isinstance(s, str):
            s = s.encode('utf-8')
        return base64.b64decode(s).decode('utf-8')

