    sep = ""

# Split by the first occurrence of any separator in the list
pattern = '|'.join(map(re.escape, sep)) if sep else None
if pattern:
    parts = re.split(pattern, seqid, 1)
    if len(parts) == 2:
        prefix, rest = parts
    else:
        prefix, rest = "", parts[0]
else:
    prefix, rest = "", seqid

# Find the numeric part (including decimals for some cases)
match = re.search(r'(\d+(\.\d+)?)', rest)
if match:
    num_id = match.group(1)
    start, end = match.span()
    prefix_rest = rest[:start]
    suffix = rest[end:]
    full_prefix = prefix + prefix_rest
else:
