def split_seq(iterable, size):
    """Splits a passed iterable into chunks of a given size."""
    chunk = []
    try:
        for _ in range(size):
            chunk.append(next(it))
        yield chunk
    except StopIteration:
        if chunk:
            yield chunk
        break

