def parameters_present(options, **kwargs):
    """
    Analysis function
    Check whether all calls contain a given parameters or their synonyms
    """
    for param, synonyms in options.items():
        all_synonyms = set(synonyms) | {param}
        if not any(k in all_synonyms for k in kwargs):
            return False
    return True

