def from_binary_string(self, notification):
        """Unpack the notification from binary string."""
        import struct
        # Assuming a standard binary format: length (4 bytes) followed by data
        # Adjust the unpacking logic based on the specific protocol requirements
        if not notification:
            return None

        try:
            length = struct.unpack('!I', notification[:4])[0]
            data = notification[4:4+length]
            return data.decode('utf-8')
        except (struct.error, UnicodeDecodeError):
            return notification

