def write(self, fn=None, sorted=False, wait=0):
        """write the contents of this config to fn or its __filename__.
        """
        if fn is None:
            fn = getattr(self, '__filename__', None)
            if fn is None:
                raise IOError("No filename provided and no __filename__ attribute found.")

        with open(fn, 'w') as f:
            data = self.to_dict() if hasattr(self, 'to_dict') else self.__dict__
            if sorted:
                import json
                json.dump(data, f, sort_keys=True, indent=4)
            else:
                import json
                json.dump(data, f, indent=4)

        if wait > 0:
            import time
            time.sleep(wait)

