def run_slurm(self, steps=None, **kwargs):
        """Run the steps via the SLURM queue."""
        if steps is None:
            steps = []

        for step in steps:
            slurm_script = self._generate_slurm_script(step, **kwargs)
            job_id = self._submit_to_slurm(slurm_script)
            self._track_job(job_id, step)

        return self._wait_for_jobs()

