import augeas
au = augeas.Augeas(load_paths=load_path.split(':') if load_path else None)

def _get_tree(node):
    res = {}
    children = au.match(f"{node}/*")
    for child in children:
        name = child.split('/')[-1]
        value = au.get(child)
        # Check if this child has children of its own
        sub_children = au.match(f"{child}/*")
        if sub_children:
            res[name] = _get_tree(child)
        else:
            res[name] = value
    return res

return _get_tree(path)

