mgc_code:
def query(wosclient, wos_query, xml_query=None, count=5, offset=1, limit=100):
    """Query Web of Science and XML query results with multiple requests."""
    results = []
    while len(results) < count and offset <= limit:
        response = wosclient.search(wos_query, offset=offset, limit=limit)
        if not response or not response.get('results'):
            break

        batch = response['results']
        for item in batch:
            if len(results) >= count:
                break
            if xml_query:
                xml_data = wosclient.get_xml(item['uid'], xml_query)
                results.append(xml_data)
            else:
                results.append(item)

        offset += len(batch)
    return results

