def _processLostJobs(self):
        """Process jobs that have gone awry"""
        lost_jobs = self.get_lost_jobs()
        for job in lost_jobs:
            try:
                self.logger.warning(f"Recovering lost job: {job.id}")
                job.mark_as_failed(reason="Job timed out or connection lost")
                self.cleanup_job_resources(job)
            except Exception as e:
                self.logger.error(f"Failed to process lost job {job.id}: {e}")
        self.refresh_job_status_cache()

