def walk(self, walk_folders=False, walk_files=False):
        """
        A simple generator that yields a File or Folder object based on
        the arguments.
        """
        for root, dirs, files in os.walk(self.path):
            if walk_folders:
                for d in dirs:
                    yield Folder(os.path.join(root, d))
            if walk_files:
                for f in files:
