def fcat(*fs):
    """Concatenate a sequence of farrays.

    The variadic *fs* input is a homogeneous sequence of functions or arrays.
    """
    items = list()
    for f in fs:
        if isinstance(f, boolfunc.Function):
            items.append(f)
        elif isinstance(f, farray):
            items.extend(f.flat)
        else:
            raise TypeError("expected Function or farray")
    return farray(items)

mgc_code:
def fcat(*fs):
    """Concatenate a sequence of farrays.

    The variadic *fs* input is a homogeneous sequence of functions or arrays.
    """
    if not fs:
        return []

    first = fs[0]
    if callable(first):
        return lambda *args, **kwargs: [item for f in fs for item in f(*args, **kwargs)]

    return [item for f in fs for item in f]

