mgc_code:
def add_file_recursive(self, filename, trim=False):
        """Add a file and all its recursive dependencies to the graph.

        Args:
          filename: The name of the file.
          trim: Whether to trim the dependencies of builtin and system files.
        """
        if filename in self.graph:
            return

        self.add_file(filename)
        dependencies = self.get_dependencies(filename)

        for dep in dependencies:
            if not trim or not self.is_builtin_or_system(dep):
                self.add_file_recursive(dep, trim=trim)

