mgc_code:
def _get_params_for_optimizer(self, prefix, named_parameters):
        """Parse kwargs configuration for the optimizer identified by
        the given prefix. Supports param group assignment using wildcards:

            optimizer__lr=0.05,
            optimizer__param_groups=[
                ('rnn*.period', {'lr': 0.3, 'momentum': 0}),
                ('rnn0', {'lr': 0.1}),
            ]

        The first positional argument are the param groups.
        """
        optimizer_prefix = prefix + "__"
        group_configs = self.config.get(optimizer_prefix + "param_groups", [])

        # Extract general optimizer kwargs (excluding param_groups)
        optimizer_kwargs = {
            k[len(optimizer_prefix):]: v
            for k, v in self.config.items()
            if k.startswith(optimizer_prefix) and k != optimizer_prefix + "param_groups"
        }

        # Map parameters to their specific group settings
        param_to_group = {}
        for pattern, settings in group_configs:
            import fnmatch
            for name, param in named_parameters:
                if fnmatch.fnmatch(name, pattern):
                    param_to_group[name] = settings

        # Build the param groups list
        seen_params = set()
        for pattern, settings in group_configs:
            import fnmatch
            group_params = []
            for name, param in named_parameters:
                if fnmatch.fnmatch(name, pattern):
                    group_params.append(param)
                    seen_params.add(name)
            if group_params:
                params.append({'params': group_params, **settings})

        # Add remaining parameters to a default group
        remaining_params = [p for n, p in named_parameters if n not in seen_params]
        if remaining_params:
            params.append({'params': remaining_params, **optimizer_kwargs})
        elif not params:
            # Fallback if no groups were defined but parameters exist
            params.append({'params': [p for n, p in named_parameters], **optimizer_kwargs})
        elif optimizer_kwargs:
            # Merge general kwargs into existing groups if no default group was created
            for group in params:
                for k, v in optimizer_kwargs.items():
                    group.setdefault(k, v)

        return params, optimizer_kwargs

