def get_algo(self, args: argparse.Namespace, algo: str) -> object:
        """ Returns machine learning algorithm based on arguments """
        algos = {
            'random_forest': RandomForestClassifier,
            'svm': SVC,
            'logistic_regression': LogisticRegression,
            'xgboost': XGBClassifier,
            'lightgbm': LGBMClassifier
        }

        if algo not in algos:
            raise ValueError(f"Algorithm {algo} not supported. Choose from {list(algos.keys())}")

        algo_class = algos[algo]
        params = {k: v for k, v in vars(args).items() if k.startswith(f"{algo}_")}
        # Remove prefix from parameter names
        clean_params = {k[len(algo)+1:]: v for k, v in params.items()}

        return algo_class(**clean_params)

