def get_expanded_schema(self, schema_name):
        """
        Return a schema file with all $ref properties expanded
        """
        import json
        import os

        schema_path = os.path.join(self.schema_dir, f"{schema_name}.json")
        with open(schema_path, 'r') as f:
            schema = json.load(f)

        def resolve_refs(obj):
            if isinstance(obj, dict):
                if '$ref' in obj:
                    ref_path = obj['$ref']
                    if ref_path.startswith('#/'):
                        # Internal reference
                        parts = ref_path.split('/')[1:]
                        curr = schema
                        for part in parts:
                            curr = curr[part]
                        return resolve_refs(curr)
                    else:
                        # External reference (assuming simple filename)
                        ext_name = ref_path.split('/')[-1].replace('.json', '')
                        return self.get_expanded_schema(ext_name)
                return {k: resolve_refs(v) for k, v in obj.items()}
            elif isinstance(obj, list):
                return [resolve_refs(item) for item in obj]
            return obj

        return resolve_refs(schema)

