def get_attributes(self):
        """This function through the layers from top to bottom, and creates a
        list of all the attributes found

        :returns: A list of all the attributes names
        :rtype: list
        """
        attributes = []
        current_layer = self
        while current_layer:
            if hasattr(current_layer, 'attributes'):
                attributes.extend(current_layer.attributes)
            if hasattr(current_layer, 'next_layer'):
                current_layer = current_layer.next_layer
            else:
                break
        return attributes

