def color(string, status=True, warning=False, bold=True):
    """
    Change text color for the linux terminal, defaults to green.
    Set "warning=True" for red.
    """
    attr = []
    if status:
        # green
        attr.append('32')
    if warning:
        # red
        attr.append('31')
    if bold:
        attr.append('1')
    return '\x1b[%sm%s\x1b[0m' % (';'.join(attr), string)

mgc_code:
def color(string, status=True, warning=False, bold=True):
    """
    Change text color for the linux terminal, defaults to green.
    Set "warning=True" for red.
    """
    colors = {
        True: "\033[32m",  # Green
        False: "\033[30m"  # Black/Default
    }
    if warning:
        color_code = "\033[31m"  # Red
    else:
        color_code = colors.get(status, "\033[0m")

    if bold:
        color_code = "\033[1m" + color_code

    return f"{color_code}{string}\033[0m"

