mgc_code:
def check_render_pipe_str(pipestr, renderers, blacklist, whitelist):
    """
    Check that all renderers specified in the pipe string are available.
    If so, return the list of render functions in the pipe as
    (render_func, arg_str) tuples; otherwise return [].
    """
    parts = pipestr.split('|')
    pipeline = []
    for part in parts:
        if not part:
            continue

        # Split renderer name from its arguments
        if ' ' in part:
            name, args = part.split(' ', 1)
        else:
            name, args = part, ''

        # Check blacklist and whitelist
        if blacklist and name in blacklist:
            return []
        if whitelist and name not in whitelist:
            return []

        # Check if renderer is available in the provided renderers map
        if name not in renderers:
            return []

        pipeline.append((renderers[name], args))

    return pipeline

