def read_meta(self, **kwargs):
        """
        Read only the annotation of the FCS file (without reading DATA segment).

        It's advised not to use this method, but instead to access
        the meta data through the FCMeasurement.meta attribute.
        """
        with open(self.filename, 'rb') as f:
            # FCS files have a TEXT segment starting at 0
            # The TEXT segment ends with 'BEGIN DATA'
            content = f.read()
            try:
                text_segment = content.split(b'BEGIN DATA')[0].decode('utf-8', errors='ignore')
            except IndexError:
                text_segment = content.decode('utf-8', errors='ignore')

            meta = {}
            for line in text_segment.splitlines():
                if '=' in line:
                    key, value = line.split('=', 1)
                    meta[key.strip()] = value.strip()
            return meta

