def run_jobs(delete_completed=False, ignore_errors=False, now=None):
    """Run scheduled jobs.

    You may specify a date to be treated as the current time.
    """
    from datetime import datetime
    from .models import Job

    current_time = now or datetime.now()
    jobs = Job.objects.filter(scheduled_time__lte=current_time, completed=False).order_by('scheduled_time')

    for job in jobs:
        try:
            job.run()
            job.completed = True
            job.completed_at = current_time
        except Exception:
            if not ignore_errors:
                raise
        finally:
            if delete_completed and job.completed:
                job.delete()
            else:
                job.save()

