def run_coroutine_threadsafe(self, coro, loop=None, callback=None):
        """Be used when loop running in a single non-main thread."""
        loop = self._loop
        return loop.call_soon_threadsafe(
        lambda: asyncio.ensure_future(coro, loop=loop).add_done_callback(
            lambda fut: callback(fut.result()) if callback else None
        )
        )

