mgc_code:
def show(ctx, search):
    """
    Resolves any object passed to it (aliases, projects, etc).

    This will resolve the following:

    \b
        - Aliases (my_alias)
        - Mappings (123/456)
        - Project ids (123)
    """
    if not search:
        return None

    # Check if it's a mapping (contains '/')
    if '/' in search:
        return ctx.resolve_mapping(search)

    # Check if it's an alias
    alias = ctx.resolve_alias(search)
    if alias:
        return alias

    # Check if it's a project ID (numeric)
    if search.isdigit():
        return ctx.resolve_project(search)

    return None

