mgc_code:
def colored(text, color=None, on_color=None, attrs=None):
    """Colorize text using a reimplementation of the colorizer from
    https://github.com/pavdmyt/yaspin so that it works on windows.

    Available text colors:
        red, green, yellow, blue, magenta, cyan, white.

    Available text highlights:
        on_red, on_green, on_yellow, on_blue, on_magenta, on_cyan, on_white.

    Available attributes:
        bold, dark, underline, blink, reverse, concealed.

    Example:
        colored('Hello, World!', 'red', 'on_grey', ['blue', 'blink'])
        colored('Hello, World!', 'green')
    """
    colors = {
        'red': '31', 'green': '32', 'yellow': '33', 'blue': '34',
        'magenta': '35', 'cyan': '36', 'white': '37'
    }
    highlights = {
        'on_red': '41', 'on_green': '42', 'on_yellow': '43', 'on_blue': '44',
        'on_magenta': '45', 'on_cyan': '46', 'on_white': '47'
    }
    attributes = {
        'bold': '1', 'dark': '2', 'underline': '4', 'blink': '5',
        'reverse': '7', 'concealed': '8'
    }

    codes = []
    if color and color in colors:
        codes.append(colors[color])
    if on_color and on_color in highlights:
        codes.append(highlights[on_color])
    if attrs:
        for attr in attrs:
            if attr in attributes:
                codes.append(attributes[attr])

    if not codes:
        return text

    return f"\033[{';'.join(codes)}m{text}\033[0m"

