mgc_code:
def value_series(self, key, start=None, end=None, interval=None,
                     namespace=None, cache=None):
        """Get a time series of gauge values"""
        if cache is None:
            cache = {}

        if namespace is None:
            namespace = self.namespace

        results = []
        current = start

        while current is None or (end is None or current <= end):
            val = self.get_value(key, timestamp=current, namespace=namespace)
            results.append((current, val))

            if interval is None:
                break
            current = current + interval if current is not None else start + interval if start is not None else None
            if current is None:
                break

        cache[key] = results
        return results

