        return use_dict

mgc_code:
def dict_contents(self, use_dict=None, as_class=dict):
        """Return the contents of an object as a dict."""
        if use_dict is None:
            use_dict = getattr(self, '__dict__', None)

        if use_dict is None:
            try:
                use_dict = dict(self)
            except (TypeError, ValueError):
                return as_class()

        return as_class(use_dict)
